const TIPO_NOTIFICACION_ICONO = { wishlist: Sparkles, anuncio: Megaphone, mensaje: MessageCircle, torneo: Calendar, plan: Shield, boost: Sparkles, error: AlertCircle, venta: Star, seguido_publico: User };

// Las notificaciones "globales" (perfil_id null, ej. Anuncios) no tienen
// dueño en la base de datos, así que no se pueden marcar "leida" ahí — se
// guarda el set de IDs ya vistas en este navegador. Las personales sí usan
// la columna `leida` de la base de datos (así se sincronizan entre
// dispositivos), y además se reflejan aquí también.
const NOTIS_LEIDAS_KEY = "ec_notis_leidas_v2";
function leerNotisLeidas() {
  try { return new Set(JSON.parse(localStorage.getItem(NOTIS_LEIDAS_KEY) || "[]")); } catch { return new Set(); }
}
function guardarNotisLeidas(set) {
  try { localStorage.setItem(NOTIS_LEIDAS_KEY, JSON.stringify([...set])); } catch {}
}

// Ícono del botón flotante de notificaciones, elegible en Apariencia
// (TEMA_ICONO_KEY -- ver theme.js) -- "default" es la campana genérica de
// siempre; el resto son los emblemas oficiales que el dueño mandó
// (public/notificaciones/*.png). Agregar un TCG nuevo a este selector es
// agregar su PNG en esa carpeta + una entrada aquí, nada más.
const ICONOS_NOTIFICACION_TCG = [
  { key: "default", label: "Genérica", img: null },
  { key: "pokemon", label: "Pokémon", img: "/notificaciones/pokemon.png" },
  { key: "magic", label: "Magic", img: "/notificaciones/magic.png" },
  { key: "onepiece", label: "One Piece", img: "/notificaciones/onepiece.png" },
  { key: "riftbound", label: "Riftbound", img: "/notificaciones/riftbound.png" },
  { key: "lorcana", label: "Lorcana", img: "/notificaciones/lorcana.png" },
  { key: "yugioh", label: "Yu-Gi-Oh!", img: "/notificaciones/yugioh.png" },
];
const ICONO_NOTIFICACION_POR_KEY = Object.fromEntries(ICONOS_NOTIFICACION_TCG.map((o) => [o.key, o.img]));

// Los PNG son una silueta negra sobre transparente (para que combinen con
// cualquier fondo de publicación) -- envueltos en una moneda clara fija
// para que se sigan viendo bien encima del botón flotante sin importar si
// el modo día/noche o el tinte por tipo lo oscurecen.
function EmblemaNotificacionImg({ src, size }) {
  const alto = Math.round(size * 1.5);
  return (
    <span style={{ width: alto, height: alto, borderRadius: "50%", background: "#F1E4D3", display: "inline-flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
      <img src={src} alt="" width={size} height={size} style={{ objectFit: "contain" }} />
    </span>
  );
}

function IconoNotificacionFlotante({ size }) {
  const key = localStorage.getItem(TEMA_ICONO_KEY) || "default";
  const src = ICONO_NOTIFICACION_POR_KEY[key];
  if (!src) return <Bell size={size} />;
  return <EmblemaNotificacionImg src={src} size={size} />;
}

// Carrito + chats en celular: en escritorio siguen siendo los botones
// flotantes grandes de siempre (abajo a la izquierda); en celular esos
// chocarían con la nueva cintilla de navegación de abajo, así que se
// reemplazan por esta cintilla chica junto al logo -- colapsada muestra
// los dos íconos en miniatura (y parpadea si hay algo pendiente en
// cualquiera de los dos), y al tocarla se despliega hacia el lado
// mostrando los botones completos con su numerito.
function CintillaMovilCarritoChats({ carritoCount, mensajesNoLeidos, mostrarChats, onCarrito, onChats }) {
  const [abierta, setAbierta] = useState(false);
  const hayPendiente = carritoCount > 0 || (mostrarChats && mensajesNoLeidos > 0);

  return (
    <div className="relative sm:hidden">
      <button onClick={() => setAbierta((v) => !v)} aria-label="Carrito y mensajes"
        style={{
          background: COLORS.surface2,
          border: `1px solid ${hayPendiente ? COLORS.gold : COLORS.azulClaro}55`,
          animation: hayPendiente ? "pulseGlow 1.4s ease-in-out infinite" : "none",
        }}
        className="flex items-center gap-1.5 rounded-full px-2.5 py-1.5">
        <ShoppingCart size={14} color={COLORS.azulPalido} />
        {/* Sin sesión no hay a dónde llevar "Chats" (la bandeja requiere
            login) -- se oculta aquí también, mismo criterio que el botón
            flotante de escritorio. */}
        {mostrarChats && <MessageCircle size={14} color={COLORS.violeta} />}
        {hayPendiente && <span style={{ width: 6, height: 6, borderRadius: "50%", background: COLORS.gold }} aria-hidden="true" />}
      </button>

      {abierta && (
        <>
          <div className="fixed inset-0 z-[69]" onClick={() => setAbierta(false)} />
          <div style={{ background: COLORS.surface2, border: `1px solid ${COLORS.azulMedio}66`, boxShadow: `0 8px 24px rgba(0,0,0,0.4)` }}
            className="absolute top-full left-0 mt-2 z-[70] rounded-xl p-2 flex gap-2">
            <button onClick={() => { onCarrito(); setAbierta(false); }}
              style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro }}
              className="relative flex flex-col items-center gap-1 rounded-lg px-4 py-2.5 whitespace-nowrap">
              <ShoppingCart size={20} />
              <span className="text-[10px] font-semibold">Carrito</span>
              {carritoCount > 0 && (
                <span style={{ background: COLORS.gold, color: COLORS.textoOscuro, border: `2px solid ${COLORS.surface2}` }}
                  className="absolute -top-1.5 -right-1.5 rounded-full text-[10px] font-bold w-5 h-5 flex items-center justify-center">
                  {carritoCount > 9 ? "9+" : carritoCount}
                </span>
              )}
            </button>
            {mostrarChats && (
              <button onClick={() => { onChats(); setAbierta(false); }}
                style={{ background: COLORS.violeta, color: "#fff" }}
                className="relative flex flex-col items-center gap-1 rounded-lg px-4 py-2.5 whitespace-nowrap">
                <MessageCircle size={20} />
                <span className="text-[10px] font-semibold">Chats</span>
                {mensajesNoLeidos > 0 && (
                  <span style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro, border: `2px solid ${COLORS.surface2}` }}
                    className="absolute -top-1.5 -right-1.5 rounded-full text-[10px] font-bold w-5 h-5 flex items-center justify-center">
                    {mensajesNoLeidos > 9 ? "9+" : mensajesNoLeidos}
                  </span>
                )}
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// Cintilla de navegación de abajo, exclusiva de celular (en escritorio
// sigue el <nav> de siempre arriba del header) -- ícono arriba, texto
// abajo, mismo espíritu que cualquier app nativa. Mismos 4 destinos que
// antes vivían arriba (Inicio/Tiendas/Catálogo/Vender), nada nuevo, solo
// cambia dónde se tocan.
function CintillaMovilAbajo({ view, setView, irAVender }) {
  const tabs = [
    { id: "search", label: "Inicio", icon: Search },
    { id: "directory", label: "Tiendas", icon: Store },
    { id: "catalogo", label: "Catálogo", icon: BookOpen },
    { id: "coleccion", label: "Colección", icon: Layers },
  ];
  const vendiendoActivo = view === "myMarket" || view === "myStore";
  const tabButton = (id, label, Icon, active, onClick) => (
    <button key={id} onClick={onClick} className="flex-1 flex flex-col items-center justify-center gap-1 py-2">
      <span style={{ background: active ? `${COLORS.azulPalido}22` : "transparent" }} className="rounded-full px-3 py-1">
        <Icon size={19} color={active ? COLORS.azulPalido : COLORS.muted} />
      </span>
      <span style={{ color: active ? COLORS.azulPalido : COLORS.muted }} className="text-[10px] font-semibold">{label}</span>
    </button>
  );
  return (
    <nav
      style={{
        background: conAlpha(COLORS.surface, 0.92), border: `1px solid ${COLORS.azulClaro}33`, backdropFilter: "blur(16px)",
        bottom: "calc(env(safe-area-inset-bottom) + 12px)", boxShadow: "0 8px 28px rgba(0,0,0,0.35)",
      }}
      className="sm:hidden fixed left-3 right-3 z-50 flex items-stretch rounded-2xl px-1"
    >
      {tabs.map((t) => tabButton(t.id, t.label, t.icon, view === t.id, () => setView(t.id)))}
      {tabButton("vender", "Vender", Tag, vendiendoActivo, irAVender)}
    </nav>
  );
}

function NotificationBell({ session, onNavigate }) {
  const [abierto, setAbierto] = useState(false);
  const [notis, setNotis] = useState([]);
  const [loading, setLoading] = useState(false);
  const [leidasLocal, setLeidasLocal] = useState(() => leerNotisLeidas());
  const [pos, setPos] = useState(null);
  const btnRef = useRef(null);

  const cargar = () => {
    setLoading(true);
    const path = session
      ? `notificaciones?select=*&or=(perfil_id.eq.${session.user.id},perfil_id.is.null)&order=created_at.desc&limit=20`
      : `notificaciones?select=*&perfil_id=is.null&order=created_at.desc&limit=20`;
    sb(path, session)
      .then(setNotis)
      .catch(() => {})
      .finally(() => setLoading(false));
  };

  useEffect(() => { cargar(); }, [session?.user?.id]);

  const esNoLeida = (n) => (n.perfil_id ? !n.leida : !leidasLocal.has(n.id));
  const noLeidas = notis.filter(esNoLeida).length;

  // Calcula la posición a partir del botón real (en vez de depender de que
  // algún ancestro tenga el ancho/posición "correcta"). El panel se manda
  // por portal a document.body (ver más abajo) precisamente porque el
  // <header> tiene backdrop-filter: blur(...), y eso convierte a cualquier
  // descendiente "position: fixed" en fijo respecto al header en vez del
  // viewport real (una regla del CSS, no un bug de este componente) — por
  // más que las coordenadas se calcularan bien, se aplicaban en el marco de
  // referencia equivocado y el panel terminaba cortado en varios celulares.
  // Con el portal, el panel ya no es descendiente del header, así que
  // "fixed" vuelve a significar "fijo respecto a la pantalla" de verdad.
  const posicionar = () => {
    const r = btnRef.current?.getBoundingClientRect();
    if (!r) return;
    const margen = 8;
    const ancho = Math.min(320, window.innerWidth - margen * 2);
    // Ancla el borde derecho del panel al del botón, pero SIEMPRE lo recorta
    // para que quede dentro de la pantalla — si solo se ancla al botón sin
    // este límite, en celulares donde la campanita no está pegada al borde
    // derecho (hay más íconos después, como el menú) el panel se sale por
    // la izquierda en vez de quedar cortado por la derecha.
    let left = r.right - ancho;
    left = Math.max(margen, Math.min(left, window.innerWidth - ancho - margen));
    setPos({ top: r.bottom + 8, left, ancho });
  };

  const abrir = () => {
    const vaAbrir = !abierto;
    setAbierto(vaAbrir);
    if (vaAbrir) {
      cargar();
      posicionar();
    }
  };

  // Vuelve a calcular la posición si cambia el tamaño de la pantalla (girar
  // el celular, aparecer/ocultarse la barra de direcciones) mientras el
  // panel sigue abierto.
  useEffect(() => {
    if (!abierto) return;
    const onResize = () => posicionar();
    window.addEventListener("resize", onResize);
    return () => window.removeEventListener("resize", onResize);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [abierto]);

  const VISTA_POR_TIPO = { wishlist: "alertas", anuncio: "news", mensaje: "inbox", venta: "comprasVentas", seguido_publico: "siguiendo" };

  // Marca como leídas todas las que están en pantalla — ver la lista ya
  // cuenta como "leído", así el numerito no depende de acertarle al click
  // exacto en cada una ni se vuelve a poner tras recargar.
  const marcarTodasLeidas = async (lista) => {
    const globales = lista.filter((n) => !n.perfil_id && !leidasLocal.has(n.id));
    if (globales.length) {
      const nuevo = new Set(leidasLocal);
      globales.forEach((n) => nuevo.add(n.id));
      setLeidasLocal(nuevo);
      guardarNotisLeidas(nuevo);
    }
    const pendientes = lista.filter((n) => n.perfil_id && !n.leida);
    if (pendientes.length) {
      setNotis((prev) => prev.map((n) => (n.perfil_id && !n.leida ? { ...n, leida: true } : n)));
      if (session) {
        await Promise.allSettled(
          pendientes.map((n) => sbWrite("PATCH", `notificaciones?id=eq.${n.id}`, { leida: true }, session).catch((e) => console.error("No se pudo marcar leída:", e)))
        );
      }
    }
  };

  useEffect(() => {
    if (abierto && !loading && notis.length > 0) marcarTodasLeidas(notis);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [abierto, loading]);

  const irA = (n) => {
    const vista = VISTA_POR_TIPO[n.tipo];
    if (vista) onNavigate?.(vista);
    setAbierto(false);
  };

  return (
    <>
      {/* Antes vivía como ícono discreto arriba del header -- ahora es un
          botón flotante en la esquina superior derecha (debajo del header
          para no encimarse con el avatar/menú que ya viven ahí), mismo
          criterio que el carrito y los chats abajo: que no dependa de
          encontrar un ícono chico entre otros. */}
      <button ref={btnRef} onClick={abrir} aria-label="Notificaciones"
        style={{ background: COLORS.surface, color: COLORS.text, border: `1px solid ${COLORS.azulClaro}55`, boxShadow: "0 6px 20px rgba(0,0,0,0.35)" }}
        className="fixed top-20 right-4 sm:top-24 sm:right-6 z-40 w-11 h-11 rounded-full flex items-center justify-center">
        <IconoNotificacionFlotante size={19} />
        {noLeidas > 0 && (
          <span style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro, border: `2px solid ${COLORS.bg}` }}
            className="absolute -top-1 -right-1 rounded-full text-[10px] font-bold w-5 h-5 flex items-center justify-center">
            {noLeidas > 9 ? "9+" : noLeidas}
          </span>
        )}
      </button>

      {abierto && pos && createPortal(
        <>
          <div className="fixed inset-0 z-[90]" onClick={() => setAbierto(false)} />
          {/* Portal a document.body + position:fixed calculado desde el botón
              real: así el panel nunca es descendiente del <header> (que tiene
              backdrop-filter, y por lo tanto redefine el marco de referencia
              de "fixed" para sus descendientes) y nunca se sale de la
              pantalla, sea cual sea el ancho del header o del dispositivo.
              z-index por encima del header (que usa 50) porque, al vivir en
              el portal, ya no comparten el mismo contexto de apilamiento. */}
          <div
            style={{
              background: COLORS.surface2, color: COLORS.text, border: `1px solid ${COLORS.azulMedio}66`, boxShadow: `0 0 24px ${COLORS.azulMedio}33`,
              position: "fixed", top: pos.top, left: pos.left, width: pos.ancho,
            }}
            className="rounded-xl overflow-hidden z-[91]"
          >
            <div className="flex items-center justify-between px-4 py-2" style={{ borderBottom: `1px solid ${COLORS.bg}` }}>
              <p className="text-sm font-semibold">Notificaciones</p>
              {noLeidas > 0 && <p style={{ color: COLORS.muted }} className="text-xs">Se marcan leídas al verlas</p>}
            </div>
            <div style={{ maxHeight: "min(320px, 60vh)", overflowY: "auto" }}>
              {loading && <p style={{ color: COLORS.muted }} className="text-xs p-4 text-center">Cargando...</p>}
              {!loading && notis.length === 0 && <p style={{ color: COLORS.muted }} className="text-xs p-4 text-center">Sin notificaciones todavía.</p>}
              {!loading && notis.map((n) => {
                const Icon = TIPO_NOTIFICACION_ICONO[n.tipo] || Bell;
                return (
                  <button key={n.id} onClick={() => irA(n)}
                    style={{ background: esNoLeida(n) ? `${COLORS.azul}22` : "transparent", borderBottom: `1px solid ${COLORS.bg}` }}
                    className="w-full text-left px-4 py-3 flex items-start gap-3 hover:brightness-125">
                    <Icon size={16} color={COLORS.azulPalido} className="mt-0.5 shrink-0" />
                    <div className="min-w-0">
                      <p className="text-sm font-medium truncate">{n.titulo}</p>
                      {n.mensaje && <p style={{ color: COLORS.muted }} className="text-xs truncate">{n.mensaje}</p>}
                      <p style={{ color: COLORS.muted }} className="text-[10px] mt-0.5">
                        {new Date(n.created_at).toLocaleDateString("es-MX", { day: "numeric", month: "short" })}
                      </p>
                    </div>
                  </button>
                );
              })}
            </div>
          </div>
        </>,
        document.body
      )}
    </>
  );
}

// Menú lateral: todo lo que no cupo en el encabezado, organizado en pestañas
// claras (Vender / Comunidad / Mi cuenta / Ayuda) en vez de una lista larga
// sin agrupar -- así nadie tiene que hacer scroll adivinando dónde está algo.
// El perfil (editar/cerrar sesión) queda fuera de las pestañas, siempre
// visible abajo, porque no pertenece a ninguna categoría de navegación.
function Drawer({ session, perfil, grupos, view, onNavigate, onEditarPerfil, onVerTutorial, onLogout, onLogin, onClose }) {
  const [tabActiva, setTabActiva] = useState(
    () => grupos.find((g) => g.items.some((it) => it.id === view))?.id || grupos[0]?.id
  );
  const grupo = grupos.find((g) => g.id === tabActiva) || grupos[0];

  const renglon = (id, label, Icon, onClick) => (
    <button
      key={id}
      onClick={onClick}
      style={{ color: view === id ? COLORS.azulPalido : COLORS.text, background: view === id ? `${COLORS.azul}22` : "transparent" }}
      className="flex items-center gap-3 w-full text-left px-4 py-3 text-sm font-medium hover:brightness-125"
    >
      <Icon size={18} /> {label}
    </button>
  );

  return (
    <div className="fixed inset-0 z-50">
      <div style={{ background: "#00000099" }} className="absolute inset-0" onClick={onClose} />
      <div style={{ background: COLORS.surface, color: COLORS.text, borderLeft: `1px solid ${COLORS.azulMedio}66` }}
        className="absolute right-0 top-0 bottom-0 w-80 max-w-[85vw] overflow-y-auto flex flex-col">
        <div className="flex items-center justify-between p-4 shrink-0" style={{ borderBottom: `1px solid ${COLORS.surface2}` }}>
          {session ? (
            <div className="flex items-center gap-2 min-w-0">
              <AvatarImg url={perfil?.avatar_url} size={36} />
              <div className="min-w-0">
                <p className="text-sm font-semibold truncate">{perfil?.nombre || "Mi cuenta"}</p>
                <PlanBadge perfil={perfil} />
              </div>
            </div>
          ) : (
            <p className="font-semibold">Menú</p>
          )}
          <button onClick={onClose} style={{ color: COLORS.muted }}><X size={20} /></button>
        </div>

        <div className="flex gap-1.5 p-3 flex-wrap shrink-0" style={{ borderBottom: `1px solid ${COLORS.surface2}` }}>
          {grupos.map((g) => {
            const GIcon = g.icon;
            const activa = g.id === tabActiva;
            return (
              <button key={g.id} onClick={() => setTabActiva(g.id)}
                style={{ background: activa ? COLORS.surface2 : "transparent", border: `1px solid ${activa ? COLORS.azulPalido : COLORS.surface2}`, color: activa ? COLORS.azulPalido : COLORS.muted }}
                className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1.5 whitespace-nowrap">
                <GIcon size={13} /> {g.label}
              </button>
            );
          })}
        </div>

        <div className="py-2 flex-1">
          {grupo.items.length === 0 ? (
            <div className="px-4 py-8 text-center">
              <p style={{ color: COLORS.muted }} className="text-sm mb-4">Inicia sesión para ver esta sección.</p>
              <button onClick={onLogin} style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro }} className="rounded-lg px-4 py-2 text-sm font-bold">
                Iniciar sesión / Crear cuenta
              </button>
            </div>
          ) : (
            grupo.items.map((item) =>
              renglon(item.id, item.label, item.icon, item.accion === "tutorial" ? onVerTutorial : () => onNavigate(item.id))
            )
          )}
        </div>

        <div style={{ borderTop: `1px solid ${COLORS.surface2}` }} className="py-2 shrink-0">
          {session ? (
            <>
              {renglon("editarPerfil", "Editar perfil", User, onEditarPerfil)}
              <button onClick={onLogout} style={{ color: COLORS.azulPalido }} className="flex items-center gap-3 w-full text-left px-4 py-3 text-sm font-medium">
                Cerrar sesión
              </button>
            </>
          ) : (
            <button onClick={onLogin} style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro }} className="mx-4 rounded-lg px-4 py-2 text-sm font-bold w-[calc(100%-2rem)]">
              Iniciar sesión / Crear cuenta
            </button>
          )}
        </div>
      </div>
    </div>
  );
}

// ---- Fondo animado global: gradiente + panal de heptágonos con parallax y brillo al tacto ----
function heptagonPath(cx, cy, r) {
  const pts = [];
  for (let i = 0; i < 7; i++) {
    const a = -Math.PI / 2 + i * ((2 * Math.PI) / 7);
    pts.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
  }
  return pts.map((p, i) => `${i === 0 ? "M" : "L"}${p[0].toFixed(2)},${p[1].toFixed(2)}`).join(" ") + " Z";
}
const HEPTA_TILE_W = 42, HEPTA_TILE_H = 72, HEPTA_R = 13;
function honeycombSvg(color, opacity) {
  const d1 = heptagonPath(HEPTA_TILE_W / 2, HEPTA_TILE_H / 4, HEPTA_R);
  const d2 = heptagonPath(0, HEPTA_TILE_H * 0.75, HEPTA_R);
  const d3 = heptagonPath(HEPTA_TILE_W, HEPTA_TILE_H * 0.75, HEPTA_R);
  const svg = `<svg xmlns='http://www.w3.org/2000/svg' width='${HEPTA_TILE_W}' height='${HEPTA_TILE_H}' viewBox='0 0 ${HEPTA_TILE_W} ${HEPTA_TILE_H}'>
    <path d='${d1}' fill='none' stroke='${color}' stroke-opacity='${opacity}' stroke-width='1'/>
    <path d='${d2}' fill='none' stroke='${color}' stroke-opacity='${opacity}' stroke-width='1'/>
    <path d='${d3}' fill='none' stroke='${color}' stroke-opacity='${opacity}' stroke-width='1'/>
  </svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}
const HEPTA_DIM = honeycombSvg(COLORS.azulClaro, 0.3);
const HEPTA_BRIGHT = honeycombSvg("#CFE0FF", 0.75);

function BackgroundField() {
  const [scrollY, setScrollY] = useState(0);
  const [pointer, setPointer] = useState({ x: -500, y: -500 });
  const [glowOn, setGlowOn] = useState(false);
  const rafRef = useRef(null);
  const fadeRef = useRef(null);

  useEffect(() => {
    const onScroll = () => {
      if (rafRef.current) return;
      rafRef.current = requestAnimationFrame(() => {
        rafRef.current = null;
        setScrollY(window.scrollY || 0);
      });
    };
    const onPointer = (e) => {
      const p = e.touches ? e.touches[0] : e;
      if (!p) return;
      clearTimeout(fadeRef.current);
      setPointer({ x: p.clientX, y: p.clientY });
      setGlowOn(true);
      fadeRef.current = setTimeout(() => setGlowOn(false), 900);
    };
    window.addEventListener("scroll", onScroll, { passive: true });
    window.addEventListener("mousemove", onPointer, { passive: true });
    window.addEventListener("touchmove", onPointer, { passive: true });
    window.addEventListener("touchstart", onPointer, { passive: true });
    return () => {
      window.removeEventListener("scroll", onScroll);
      window.removeEventListener("mousemove", onPointer);
      window.removeEventListener("touchmove", onPointer);
      window.removeEventListener("touchstart", onPointer);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
      clearTimeout(fadeRef.current);
    };
  }, []);

  const bgPos = `0px ${scrollY * 0.35}px`;

  return (
    <>
      <div
        style={{
          position: "fixed", inset: "-10%", zIndex: 0, pointerEvents: "none",
          animation: "drift 22s ease-in-out infinite",
          background: `radial-gradient(60% 50% at 15% 8%, rgba(79,127,209,.28), transparent 60%),
            radial-gradient(50% 45% at 85% 15%, rgba(139,92,246,.16), transparent 60%),
            radial-gradient(70% 60% at 50% 95%, rgba(255,211,77,.08), transparent 60%),
            linear-gradient(180deg, ${COLORS.bg} 0%, ${COLORS.surface} 45%, ${COLORS.fondoProfundo} 100%)`,
        }}
      />
      <div
        style={{
          position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none", opacity: 0.32,
          backgroundImage: `url("${HEPTA_DIM}")`,
          backgroundSize: `${HEPTA_TILE_W}px ${HEPTA_TILE_H}px`,
          backgroundPosition: bgPos, backgroundRepeat: "repeat",
          maskImage: "linear-gradient(180deg, rgba(0,0,0,0.85), rgba(0,0,0,0.45) 55%, rgba(0,0,0,0.1))",
          WebkitMaskImage: "linear-gradient(180deg, rgba(0,0,0,0.85), rgba(0,0,0,0.45) 55%, rgba(0,0,0,0.1))",
        }}
      />
      <div
        style={{
          position: "fixed", inset: 0, zIndex: 0, pointerEvents: "none", mixBlendMode: "screen",
          transition: "opacity .5s ease", opacity: glowOn ? 0.5 : 0,
          backgroundImage: `url("${HEPTA_BRIGHT}")`,
          backgroundSize: `${HEPTA_TILE_W}px ${HEPTA_TILE_H}px`,
          backgroundPosition: bgPos, backgroundRepeat: "repeat",
          maskImage: `radial-gradient(circle 130px at ${pointer.x}px ${pointer.y}px, rgba(0,0,0,0.9), transparent 70%)`,
          WebkitMaskImage: `radial-gradient(circle 130px at ${pointer.x}px ${pointer.y}px, rgba(0,0,0,0.9), transparent 70%)`,
        }}
      />
    </>
  );
}

// ---- Distancia en línea recta entre dos coordenadas (fórmula de Haversine) ----
function distanciaKm(lat1, lng1, lat2, lng2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLng = ((lng2 - lng1) * Math.PI) / 180;
  const a = Math.sin(dLat / 2) ** 2 + Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLng / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}
const formatoDistancia = (km) => (km < 1 ? `${Math.round(km * 1000)} m` : `${km.toFixed(1)} km`);

// ---- Búsqueda del Mercado/tiendas por palabras sueltas contra nombre y set ----
// Para que "Sprigatito 016", "Sprigatito #016" o "Sprigatito Journey Together"
// encuentren una publicación sin importar el orden: cada palabra debe aparecer
// en el nombre de la carta O en su set_nombre (que ya guarda cosas como
// "Journey Together 016/159"), sin exigir que toda la frase esté en un solo campo.
function filtroPalabrasCartaOSet(texto, campoExtra) {
  const palabras = (texto || "")
    .trim()
    .split(/\s+/)
    .map((w) => w.replace(/^#/, ""))
    .filter(Boolean);
  if (!palabras.length) return "";
  const grupos = palabras.map((w) => {
    const valor = encodeURIComponent(pgLikeValor(w));
    const campos = [`carta.ilike.${valor}`, `set_nombre.ilike.${valor}`];
    // etiquetas_texto: para que un accesorio (mercado_listings.tipo="accesorio")
    // aparezca al buscar una palabra clave (ej. "sylveon") aunque no sea el
    // nombre del producto ni exista como carta — ver migración 046.
    if (campoExtra) campos.push(`${campoExtra}.ilike.${valor}`);
    return `or(${campos.join(",")})`;
  });
  return `and=(${grupos.join(",")})`;
}

// ---- Geocodificación: convierte una dirección en texto a lat/lng ----
// Usa Nominatim (OpenStreetMap), gratis y sin necesitar API key.
async function buscarCoordenadasPorDireccion(direccion) {
  const q = encodeURIComponent(direccion);
  const res = await fetch(`https://nominatim.openstreetmap.org/search?format=json&limit=1&countrycodes=mx&q=${q}`);
  if (!res.ok) throw new Error("No se pudo buscar la dirección.");
  const data = await res.json();
  if (!data?.length) throw new Error("No se encontró esa dirección. Prueba escribirla más completa (calle, número, colonia, ciudad).");
  return { lat: Number(data[0].lat), lng: Number(data[0].lon) };
}

// ---- Slugs (link propio de cada perfil/tienda, ej. "carta-magica-monterrey") ----
// Misma lógica que la función slugify() de Postgres (migración 041), para que un
// slug calculado en el navegador coincida con lo que ya generó la base de datos.
function slugify(texto) {
  const limpio = (texto || "")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // quita acentos
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "");
  return limpio || null;
}

// Crea una fila con un slug único: intenta con el slug base y, si ya existe
// (choque con otro nombre parecido), reintenta agregando "-2", "-3"... en vez
// de bloquear el registro. Después de varios intentos, usa un sufijo corto
// garantizado único para no quedarse trabado.
async function crearConSlugUnico(tabla, datosBase, nombreParaSlug, session, fallbackPrefijo) {
  const base = slugify(nombreParaSlug) || `${fallbackPrefijo}-${Math.random().toString(36).slice(2, 8)}`;
  for (let intento = 1; intento <= 20; intento++) {
    const slug = intento === 1 ? base : `${base}-${intento}`;
    try {
      return await sbWrite("POST", tabla, { ...datosBase, slug }, session);
    } catch (e) {
      if (e.code !== "23505" || intento === 20) throw e;
    }
  }
}

// ---- Carrito: agrupa lo agregado por vendedor y manda un solo mensaje por
// vendedor (con la lista de lo que le interesa) en vez de chatear uno por uno. ----
function CarritoView({ carrito, onQuitar, onRequireLogin, onEnviado, session }) {
  const [mensaje, setMensaje] = useState("Hola, me interesa lo siguiente que tienes publicado, ¿sigue disponible?");
  const [enviando, setEnviando] = useState(false);
  const [resultado, setResultado] = useState(null);
  const [error, setError] = useState(null);

  if (!session) {
    return (
      <div className="text-center py-16">
        <p style={{ color: COLORS.muted }} className="text-sm mb-4">Inicia sesión para usar el carrito.</p>
        <button onClick={onRequireLogin} style={{ background: COLORS.azulClaro, color: COLORS.textoOscuro }} className="rounded-lg px-4 py-2 text-sm font-semibold">Iniciar sesión</button>
      </div>
    );
  }

  if (resultado) {
    return <p style={{ color: COLORS.azulPalido }} className="text-sm text-center py-16">{resultado}</p>;
  }

  if (carrito.length === 0) {
    return <p style={{ color: COLORS.muted }} className="text-center py-16 text-sm">Tu carrito está vacío. Agrega cartas o producto sellado desde Buscar, Mercado o el directorio de tiendas con el botón 🛒.</p>;
  }

  const grupos = {};
  for (const it of carrito) {
    const key = it.vendedorId || "sin-vendedor";
    if (!grupos[key]) grupos[key] = { vendedorId: it.vendedorId, nombre: it.vendedorNombre, avatar: it.vendedorAvatar, whatsapp: it.vendedorWhatsapp, facebook: it.vendedorFacebook, items: [] };
    grupos[key].items.push(it);
  }
  const listaGrupos = Object.values(grupos);
  const total = carrito.reduce((s, it) => s + Number(it.precio || 0), 0);

  const enviarATodos = async () => {
    if (!mensaje.trim()) return;
    setEnviando(true); setError(null);
    try {
      for (const g of listaGrupos) {
        if (!g.vendedorId) continue;
        const listado = g.items.map((it) => `• ${it.nombre}${it.precio ? ` — $${Number(it.precio).toLocaleString("es-MX")}` : ""}`).join("\n");
        await sbWrite("POST", "mensajes", {
          de_perfil_id: session.user.id,
          para_perfil_id: g.vendedorId,
          texto: `${mensaje.trim()}\n\n${listado}`,
          contexto: "Carrito",
          listing_id: g.items[0].tabla === "mercado_listings" ? g.items[0].id : null,
        }, session);
      }
      setResultado(`Listo: mandamos tu mensaje a ${listaGrupos.length} vendedor${listaGrupos.length === 1 ? "" : "es"}.`);
      onEnviado();
    } catch (e) { setError(e.message); } finally { setEnviando(false); }
  };

  return (
    <div>
      <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-xl font-bold mb-1">🛒 Carrito</h2>
      <p style={{ color: COLORS.muted }} className="text-sm mb-4">
        Un mensaje por vendedor, con todo lo que te interesa de él, en vez de escribirle uno por uno.
      </p>
      {error && <div className="mb-4"><ErrorBox message={error} /></div>}

      <div className="grid gap-4 mb-6">
        {listaGrupos.map((g) => (
          <div key={g.vendedorId || "sin-vendedor"} style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-4">
            <div className="flex items-center gap-2 mb-2">
              <AvatarImg url={g.avatar} size={24} />
              <p className="text-sm font-semibold">{g.nombre || "Vendedor"}</p>
            </div>
            <div className="grid gap-1">
              {g.items.map((it) => (
                <div key={`${it.tabla}-${it.id}`} className="flex items-center justify-between gap-2 text-sm">
                  <div className="flex items-center gap-2 min-w-0">
                    {it.imagen_url && <img src={it.imagen_url} alt="" style={{ width: 32, height: 44, objectFit: "contain" }} />}
                    <p className="truncate">{it.nombre}</p>
                  </div>
                  <div className="flex items-center gap-2 whitespace-nowrap">
                    {it.precio != null && <p style={{ fontFamily: "'Cabin', sans-serif", color: COLORS.azulPalido }}>${Number(it.precio).toLocaleString("es-MX")}</p>}
                    <button onClick={() => onQuitar(it.tabla, it.id)} style={{ color: "#C24444" }}><X size={14} /></button>
                  </div>
                </div>
              ))}
            </div>
          </div>
        ))}
      </div>

      <p style={{ color: COLORS.muted }} className="text-sm mb-3">
        Total aproximado: <span style={{ color: COLORS.gold, fontFamily: "'Cabin', sans-serif" }}>${total.toLocaleString("es-MX")}</span>
      </p>
      <textarea value={mensaje} onChange={(e) => setMensaje(e.target.value)} rows={3}
        style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }}
        className="rounded-lg px-3 py-2 text-sm w-full outline-none mb-3" placeholder="Escribe tu mensaje..." />
      <button onClick={enviarATodos} disabled={enviando || !mensaje.trim()}
        style={{ background: COLORS.azulClaro, color: COLORS.textoOscuro, opacity: enviando ? 0.6 : 1 }}
        className="rounded-lg py-2.5 px-4 text-sm font-semibold flex items-center gap-2">
        {enviando && <Loader2 size={16} className="animate-spin" />} Enviar mensaje a {listaGrupos.length} vendedor{listaGrupos.length === 1 ? "" : "es"}
      </button>
    </div>
  );
}

// ---- Catálogo: era > set > cartas, con marcado Tengo/Quiero (Amatista+).
// Navega en 3 niveles con el mismo state (eraSel/setSel null = nivel
// anterior) en vez de un router — mismo patrón que el resto de la app
// (view/selectedX en el componente raíz). Los 8 TCG agregados vía
// apitcg.com (Cardfight Vanguard, Digimon, Dragon Ball Super Fusion World/
// Masters, Flesh and Blood, Gundam, hololive, Riftbound) ya entran por
// obtenerErasYSetsCatalogo/obtenerCartasDeSetCatalogo como cualquier otro
// TCG -- ver sección 152 de SUSCRIPCIONES.md. Solo One Piece sigue aparte:
// sus sets salen de TCGCSV, igual que TCGplayerPicker.
function CatalogoView({ session, perfil, onIrAPlanes }) {
  const info = planDe(perfil);
  const [tcgSel, setTcgSel] = useState("pokemon");
  const [eras, setEras] = useState([]);
  const [loadingEras, setLoadingEras] = useState(true);
  const [eraSel, setEraSel] = useState(null);
  const [setSel, setSetSel] = useState(null);
  const [cartas, setCartas] = useState([]);
  const [loadingCartas, setLoadingCartas] = useState(false);
  const [categoriaIdOP, setCategoriaIdOP] = useState(null);
  const [coleccion, setColeccion] = useState({}); // card_api_id -> "tengo" | "quiero"
  const [error, setError] = useState(null);
  const [modo, setModo] = useState("explorar"); // explorar | masterSets
  const [volverAMasterSets, setVolverAMasterSets] = useState(false);
  const [misMazosTcg, setMisMazosTcg] = useState([]);
  const [mazoDestino, setMazoDestino] = useState("");
  const [agregandoMazoId, setAgregandoMazoId] = useState(null);
  const [misTengoSets, setMisTengoSets] = useState({}); // set_nombre -> cantidad marcada "tengo"
  // Mismo problema que el efecto de tcgSel: si entras a un set y le das clic
  // a otro antes de que termine de cargar, la respuesta del primero puede
  // llegar después y pisar las cartas del segundo (o dejarlo en "sin
  // cartas" si esa fue la que falló). abrirSetTokenRef descarta cualquier
  // respuesta que ya no sea la del set vigente.
  const abrirSetTokenRef = useRef(0);

  useEffect(() => {
    // Si cambias de categoría rápido (Pokémon → Magic → Pokémon), quedan
    // varias peticiones en vuelo a la vez -- sin esto, la que responde AL
    // ÚLTIMO gana el estado aunque ya no sea la categoría seleccionada, y
    // si esa era la que falló/tardó, se veía "no hay sets disponibles"
    // hasta que algo más disparaba el efecto de nuevo (entrar y salir 2-3
    // veces). `cancelado` descarta cualquier respuesta que ya no aplique.
    let cancelado = false;
    setEraSel(null); setSetSel(null); setCartas([]); setError(null);
    setLoadingEras(true);
    (async () => {
      if (tcgSel === "onepiece") {
        const catId = await categoriaIdTCGplayer("onepiece");
        if (cancelado) return;
        setCategoriaIdOP(catId);
        if (!catId) { setEras([]); setLoadingEras(false); return; }
        try {
          const res = await fetch(`/api/tcgcsv?path=tcgplayer/${catId}/groups`);
          const data = await res.json();
          if (cancelado) return;
          const sets = (data.results || [])
            .slice()
            .sort((a, b) => (b.publishedOn || "").localeCompare(a.publishedOn || ""))
            .map((g) => ({ id: g.groupId, nombre: g.name, cardCount: null, imagen: null }));
          setEras([{ era: null, sets }]);
        } catch { if (!cancelado) setEras([]); }
        if (!cancelado) setLoadingEras(false);
        return;
      }
      try {
        const resultado = await obtenerErasYSetsCatalogo(tcgSel);
        if (!cancelado) setEras(resultado);
      } catch {
        if (!cancelado) setEras([]);
      } finally {
        if (!cancelado) setLoadingEras(false);
      }
    })();
    return () => { cancelado = true; };
  }, [tcgSel]);

  useEffect(() => {
    if (!session) { setColeccion({}); return; }
    sb(`coleccion_usuario?select=card_api_id,estado&perfil_id=eq.${session.user.id}&tcg=eq.${tcgSel}`, session)
      .then((rows) => setColeccion(Object.fromEntries(rows.map((r) => [r.card_api_id, r.estado]))))
      .catch(() => setColeccion({}));
  }, [tcgSel, session]);

  // Mazos de este TCG (para poder agregar una carta del catálogo directo a uno) —
  // Deck Builder es Amatista+ (info.mazoBuilder), igual que en "Armar mazo".
  useEffect(() => {
    if (!session || !info.mazoBuilder) { setMisMazosTcg([]); setMazoDestino(""); return; }
    sb(`mazos?select=id,nombre&perfil_id=eq.${session.user.id}&tcg=eq.${tcgSel}&order=nombre.asc`, session)
      .then((rows) => { setMisMazosTcg(rows); setMazoDestino((prev) => (rows.some((r) => r.id === prev) ? prev : (rows[0]?.id || ""))); })
      .catch(() => setMisMazosTcg([]));
  }, [tcgSel, session, info.mazoBuilder]);

  // Master Sets: cuántas cartas de cada set ya marcaste como "tengo".
  useEffect(() => {
    if (!session || !info.wishlistPremium) { setMisTengoSets({}); return; }
    sb(`coleccion_usuario?select=set_nombre&perfil_id=eq.${session.user.id}&tcg=eq.${tcgSel}&estado=eq.tengo`, session)
      .then((rows) => {
        const conteo = {};
        for (const r of rows) { if (!r.set_nombre) continue; conteo[r.set_nombre] = (conteo[r.set_nombre] || 0) + 1; }
        setMisTengoSets(conteo);
      })
      .catch(() => setMisTengoSets({}));
  }, [tcgSel, session, info.wishlistPremium]);

  const agregarAMazo = async (carta) => {
    if (!mazoDestino || !session) return;
    setAgregandoMazoId(carta.id);
    try {
      const existentes = await sb(`mazo_cartas?select=id,cantidad&mazo_id=eq.${mazoDestino}&card_api_id=eq.${encodeURIComponent(carta.id)}`, session);
      if (existentes[0]) {
        await sbWrite("PATCH", `mazo_cartas?id=eq.${existentes[0].id}`, { cantidad: existentes[0].cantidad + 1 }, session);
      } else {
        await sbWrite("POST", "mazo_cartas", { mazo_id: mazoDestino, nombre: carta.name, set_nombre: setSel?.nombre || null, card_api_id: carta.id, imagen_url: carta.image, cantidad: 1 }, session);
      }
    } catch (e) { setError(e.message); } finally { setAgregandoMazoId(null); }
  };

  const abrirSetDesdeMasterSets = (s) => {
    const eraDelSet = eras.find((g) => g.sets.some((x) => x.id === s.id))?.era;
    setEraSel(eraDelSet ?? null);
    setModo("explorar");
    setVolverAMasterSets(true);
    abrirSet(s);
  };

  const abrirSet = async (set) => {
    const miToken = ++abrirSetTokenRef.current;
    setSetSel(set); setLoadingCartas(true); setCartas([]); setError(null);
    try {
      if (tcgSel === "onepiece") {
        const [dataProd, dataPrecios] = await Promise.all([
          fetch(`/api/tcgcsv?path=tcgplayer/${categoriaIdOP}/${set.id}/products`).then((r) => r.json()),
          fetch(`/api/tcgcsv?path=tcgplayer/${categoriaIdOP}/${set.id}/prices`).then((r) => r.json()),
        ]);
        if (abrirSetTokenRef.current !== miToken) return;
        const productos = (dataProd.results || []).filter(looksLikeCard);
        const precios = dataPrecios.results || [];
        setCartas(productos.map((p) => {
          const precioInfo = precios.find((x) => x.productId === p.productId && x.marketPrice);
          return {
            id: `tcgcsv-${p.productId}`, name: p.name, localId: "", image: p.imageUrl || null,
            precioRefMxn: precioInfo ? Math.round(precioInfo.marketPrice * USD_TO_MXN) : null,
          };
        }));
      } else {
        const resultado = await obtenerCartasDeSetCatalogo(tcgSel, set.id);
        if (abrirSetTokenRef.current !== miToken) return;
        setCartas(resultado);
      }
    } catch (e) { if (abrirSetTokenRef.current === miToken) setError(e.message); } finally { if (abrirSetTokenRef.current === miToken) setLoadingCartas(false); }
  };

  const marcar = async (carta, estado) => {
    if (!session) { onIrAPlanes?.(); return; }
    // "Quiero" (wishlist básica) es gratis para todos los que tengan sesión;
    // "Tengo" (para llevar el progreso real en Master Sets) sigue exclusivo
    // Amatista+, ver info.wishlistPremium.
    if (estado === "tengo" && !info.wishlistPremium) { onIrAPlanes?.(); return; }
    const actual = coleccion[carta.id];
    const nuevoEstado = actual === estado ? null : estado;
    setColeccion((prev) => {
      const n = { ...prev };
      if (nuevoEstado) n[carta.id] = nuevoEstado; else delete n[carta.id];
      return n;
    });
    try {
      if (actual) {
        await sbWrite("DELETE", `coleccion_usuario?perfil_id=eq.${session.user.id}&tcg=eq.${tcgSel}&card_api_id=eq.${encodeURIComponent(carta.id)}`, {}, session);
      }
      if (nuevoEstado) {
        // "quiero" ya no se espeja también en la tabla wishlist (vieja,
        // sin imagen) -- coleccion_usuario es autosuficiente para la
        // Wishlist rediseñada (carpeta visual + link público, ver
        // MiWishlistView/WishlistPublicaView) y ya trae su propio
        // unique(perfil_id, tcg, card_api_id) para el dedup.
        await sbWrite("POST", "coleccion_usuario", {
          perfil_id: session.user.id, tcg: tcgSel, card_api_id: carta.id, carta: carta.name,
          set_nombre: setSel?.nombre || null, imagen_url: carta.image || null, estado: nuevoEstado,
        }, session);
      }
    } catch (e) { setError(e.message); }
  };

  const grupoUnico = eras.length === 1 && eras[0].era === null ? eras[0] : null;
  const tengoCount = cartas.filter((c) => coleccion[c.id] === "tengo").length;
  const quieroCount = cartas.filter((c) => coleccion[c.id] === "quiero").length;

  return (
    <div>
      <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-xl font-bold mb-1">📚 Catálogo</h2>
      {/* Una vez que ya se eligió un set y se están viendo/marcando cartas
          (Paso 3), esta explicación de los 3 pasos y el selector de juego de
          arriba ya no aportan nada -- solo saturan la pantalla con
          información que ya no se usa. Se ocultan en ese momento; para
          cambiar de juego basta con volver atrás por el breadcrumb de abajo. */}
      {!setSel && (
        <>
          <p style={{ color: COLORS.muted }} className="text-sm mb-4">
            Paso 1: elige el juego. Paso 2: elige una era y un set. Paso 3: marca cada carta con ✅ Tengo o ⭐ Quiero.
          </p>
          <p style={{ color: COLORS.muted }} className="text-xs font-semibold uppercase mb-2">Paso 1 · Elige el juego</p>
          <div className="flex gap-2 flex-wrap mb-6">
            {TCG_OPCIONES.map((o) => (
              <button key={o.key} onClick={() => setTcgSel(o.key)}
                style={{ background: tcgSel === o.key ? `${COLORS.azul}55` : COLORS.surface2, border: `1px solid ${tcgSel === o.key ? COLORS.azulPalido : COLORS.surface2}`, color: tcgSel === o.key ? COLORS.azulPalido : COLORS.muted }}
                className="rounded-lg px-3 py-1.5 text-xs font-semibold">
                {o.label}
              </button>
            ))}
          </div>
        </>
      )}
      {error && <div className="mb-4"><ErrorBox message={error} /></div>}

      {!info.wishlistPremium && (
        <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-4 mb-6 flex items-center justify-between gap-4 flex-wrap">
          <p style={{ color: COLORS.muted }} className="text-sm">🔒 Marcar ✅ "Tengo" (y ver tu progreso en "Mi progreso por set") es exclusivo del plan Amatista en adelante — marcar ⭐ "Quiero" ya es gratis para todos.</p>
          <button onClick={onIrAPlanes} style={{ color: COLORS.azulClaro, border: `1px solid ${COLORS.azulClaro}55` }} className="text-xs px-3 py-1.5 rounded-lg whitespace-nowrap">Ver planes</button>
        </div>
      )}

      {info.wishlistPremium && (
        <div className="mb-6">
          <p style={{ color: COLORS.muted }} className="text-xs font-semibold uppercase mb-2">¿Qué quieres hacer?</p>
          <div className="flex gap-2 flex-wrap">
            <button onClick={() => { setModo("explorar"); setVolverAMasterSets(false); }}
              style={{ background: modo === "explorar" ? COLORS.surface2 : "transparent", border: `1px solid ${modo === "explorar" ? COLORS.azulPalido : COLORS.surface2}`, color: modo === "explorar" ? COLORS.azulPalido : COLORS.muted }}
              className="rounded-lg px-4 py-2 text-sm font-semibold text-left">
              📖 Ver cartas y marcar<br />
              <span style={{ color: COLORS.muted, fontWeight: 400 }} className="text-xs">Buscar un set y marcar Tengo/Quiero</span>
            </button>
            <button onClick={() => { setModo("masterSets"); setVolverAMasterSets(false); setSetSel(null); setCartas([]); }}
              style={{ background: modo === "masterSets" ? COLORS.surface2 : "transparent", border: `1px solid ${modo === "masterSets" ? COLORS.azulPalido : COLORS.surface2}`, color: modo === "masterSets" ? COLORS.azulPalido : COLORS.muted }}
              className="rounded-lg px-4 py-2 text-sm font-semibold text-left">
              🏆 Mi progreso por set<br />
              <span style={{ color: COLORS.muted, fontWeight: 400 }} className="text-xs">Ver qué tan completa tienes cada colección</span>
            </button>
          </div>
        </div>
      )}

      {modo === "masterSets" && info.wishlistPremium && (
        <div className="grid gap-3">
          <p style={{ color: COLORS.muted }} className="text-sm -mt-2 mb-1">Qué tan completa tienes cada colección, según las cartas que marcaste ✅ Tengo.</p>
          {loadingEras && <Loading label="Cargando sets..." />}
          {!loadingEras && eras.flatMap((g) => g.sets).length === 0 && (
            <p style={{ color: COLORS.muted }} className="text-sm">No pudimos cargar los sets de {TCG_LABEL[tcgSel]} en este momento.</p>
          )}
          {!loadingEras && eras.flatMap((g) => g.sets).map((s) => {
            const tengo = misTengoSets[s.nombre] || 0;
            const total = s.cardCount || null;
            const pct = total ? Math.min(100, Math.round((tengo / total) * 100)) : null;
            return (
              <div key={s.id} style={{ background: COLORS.surface, border: `1px solid ${pct === 100 ? COLORS.gold + "88" : COLORS.surface2}` }} className="rounded-xl p-4">
                <div className="flex items-center justify-between gap-3 flex-wrap mb-2">
                  <div className="flex items-center gap-2">
                    {s.imagen && <img src={s.imagen} alt="" style={{ maxHeight: 28, maxWidth: 70, objectFit: "contain" }} />}
                    <p className="font-semibold text-sm">{s.nombre}</p>
                  </div>
                  <button onClick={() => abrirSetDesdeMasterSets(s)} style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55` }} className="text-xs px-3 py-1.5 rounded-lg">Ver cartas</button>
                </div>
                {total ? (
                  <>
                    <div style={{ background: COLORS.surface2, height: 8, borderRadius: 4, overflow: "hidden" }}>
                      <div style={{ width: `${pct}%`, height: "100%", background: pct === 100 ? COLORS.gold : COLORS.azulPalido }} />
                    </div>
                    <p style={{ color: COLORS.muted }} className="text-xs mt-1">{tengo} / {total} cartas ({pct}%){pct === 100 ? " 🏆 ¡Completo!" : ""}</p>
                  </>
                ) : (
                  <p style={{ color: COLORS.muted }} className="text-xs">{tengo} carta{tengo === 1 ? "" : "s"} marcada{tengo === 1 ? "" : "s"} como "tengo" (el total de este set no está disponible).</p>
                )}
              </div>
            );
          })}
        </div>
      )}

      {modo === "explorar" && !grupoUnico && (eraSel || setSel) && (
        <div className="flex items-center gap-1 flex-wrap text-xs mb-4" style={{ color: COLORS.muted }}>
          <span>📍</span>
          <button onClick={() => { setEraSel(null); setSetSel(null); setCartas([]); }} style={{ color: COLORS.azulPalido }} className="hover:underline">{TCG_LABEL[tcgSel]}</button>
          <span>›</span>
          <button onClick={() => { setSetSel(null); setCartas([]); }} style={{ color: setSel ? COLORS.azulPalido : COLORS.text }} className={setSel ? "hover:underline" : "font-semibold"}>{eraSel}</button>
          {setSel && (<><span>›</span><span style={{ color: COLORS.text }} className="font-semibold">{setSel.nombre}</span></>)}
        </div>
      )}

      {modo === "explorar" && loadingEras && <Loading label="Cargando sets..." />}

      {modo === "explorar" && !loadingEras && !setSel && (
        <>
          {!grupoUnico && !eraSel && (
            <div>
              <p style={{ color: COLORS.muted }} className="text-xs font-semibold uppercase mb-2">Paso 2 · Elige una era (agrupa varios sets de esa etapa del juego)</p>
              <div className="grid sm:grid-cols-2 gap-3">
                {eras.length === 0 && <p style={{ color: COLORS.muted }} className="text-sm">No pudimos cargar el catálogo de {TCG_LABEL[tcgSel]} en este momento.</p>}
                {eras.map((g) => (
                  <button key={g.era} onClick={() => setEraSel(g.era)}
                    style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }}
                    className="rounded-xl p-4 text-left hover:brightness-125 flex items-center gap-3">
                    {g.imagen && <img src={g.imagen} alt="" style={{ maxHeight: 36, maxWidth: 90, objectFit: "contain" }} />}
                    <div>
                      <p className="font-semibold">{g.era}</p>
                      <p style={{ color: COLORS.muted }} className="text-xs">{g.sets.length} set{g.sets.length === 1 ? "" : "s"}</p>
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          {(grupoUnico || eraSel) && (
            <div>
              <p style={{ color: COLORS.muted }} className="text-xs font-semibold uppercase mb-2">Paso 2 · Elige un set</p>
              {(grupoUnico || eras.find((g) => g.era === eraSel))?.sets.length === 0 && (
                <p style={{ color: COLORS.muted }} className="text-sm">No pudimos cargar los sets de {TCG_LABEL[tcgSel]} en este momento.</p>
              )}
              <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-3">
                {(grupoUnico || eras.find((g) => g.era === eraSel))?.sets.map((s) => (
                  <button key={s.id} onClick={() => abrirSet(s)}
                    style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }}
                    className="rounded-xl p-4 text-left hover:brightness-125 flex items-center gap-3">
                    {s.imagen && <img src={s.imagen} alt="" style={{ maxHeight: 32, maxWidth: 80, objectFit: "contain" }} />}
                    <div>
                      <p className="font-semibold text-sm">{s.nombre}</p>
                      {s.cardCount && <p style={{ color: COLORS.muted }} className="text-xs">{s.cardCount} cartas</p>}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}
        </>
      )}

      {modo === "explorar" && setSel && (
        <div>
          <button
            onClick={() => {
              setSetSel(null); setCartas([]);
              if (volverAMasterSets) { setModo("masterSets"); setVolverAMasterSets(false); }
            }}
            style={{ color: COLORS.muted }} className="text-xs mb-3 flex items-center gap-1">
            <ChevronLeft size={14} /> {volverAMasterSets ? "Volver a Mi progreso" : "Volver a todos los sets"}
          </button>
          <p style={{ color: COLORS.muted }} className="text-xs font-semibold uppercase mb-2">Paso 3 · Marca cada carta</p>
          <div className="flex items-center justify-between gap-3 flex-wrap mb-4">
            <h3 className="font-semibold">{setSel.nombre}</h3>
            {session && info.wishlistPremium && cartas.length > 0 && (
              <p style={{ color: COLORS.muted }} className="text-xs">✅ Tengo: {tengoCount} · ⭐ Quiero: {quieroCount} de {cartas.length}</p>
            )}
          </div>

          {info.mazoBuilder && (
            misMazosTcg.length > 0 ? (
              <div className="flex items-center gap-2 flex-wrap mb-4">
                <p style={{ color: COLORS.muted }} className="text-xs">🧩 Agregar cartas al mazo:</p>
                <select value={mazoDestino} onChange={(e) => setMazoDestino(e.target.value)} style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-1.5 text-xs">
                  {misMazosTcg.map((m) => <option key={m.id} value={m.id}>{m.nombre}</option>)}
                </select>
              </div>
            ) : (
              <p style={{ color: COLORS.muted }} className="text-xs mb-4">Crea un mazo de {TCG_LABEL[tcgSel]} en "Armar mazo" para poder agregar cartas directo desde aquí.</p>
            )
          )}

          {loadingCartas && <SkeletonGrid n={12} />}
          {!loadingCartas && !error && cartas.length === 0 && <p style={{ color: COLORS.muted }} className="text-sm">Sin cartas para este set.</p>}
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
            {cartas.map((c) => {
              const estado = coleccion[c.id];
              return (
                <div key={c.id} style={{ background: `${COLORS.surface2}99`, border: `1px solid ${estado === "tengo" ? "#2E8B5766" : estado === "quiero" ? COLORS.azulPalido + "66" : COLORS.azulClaro + "29"}` }} className="rounded-xl overflow-hidden flex flex-col">
                  <div style={{ background: COLORS.surface2 }} className="aspect-[3/4] flex items-center justify-center p-2">
                    {c.image ? <img src={c.image} alt={c.name} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} /> : <Package size={32} color={COLORS.muted} />}
                  </div>
                  <div className="p-2 flex flex-col gap-1">
                    <p className="text-xs font-semibold leading-snug line-clamp-2">{c.name}{c.localId ? ` (${c.localId})` : ""}</p>
                    {c.precioRefMxn ? (
                      <p style={{ fontFamily: "'Cabin', sans-serif", color: COLORS.gold }} className="text-xs font-bold">~${c.precioRefMxn.toLocaleString("es-MX")} MXN</p>
                    ) : (
                      <p style={{ color: COLORS.muted }} className="text-xs">Sin precio de referencia</p>
                    )}
                    <div className="flex gap-1">
                      <button onClick={() => marcar(c, "tengo")}
                        style={{ background: estado === "tengo" ? "#2E8B57" : "transparent", border: "1px solid #2E8B5788", color: estado === "tengo" ? "#fff" : "#2E8B57" }}
                        className="flex-1 rounded-lg py-1 text-[11px] font-semibold">
                        ✅ Tengo
                      </button>
                      <button onClick={() => marcar(c, "quiero")}
                        style={{ background: estado === "quiero" ? COLORS.azulPalido : "transparent", border: `1px solid ${COLORS.azulPalido}88`, color: estado === "quiero" ? COLORS.textoOscuro : COLORS.azulPalido }}
                        className="flex-1 rounded-lg py-1 text-[11px] font-semibold">
                        ⭐ Quiero
                      </button>
                    </div>
                    {info.mazoBuilder && misMazosTcg.length > 0 && (
                      <button onClick={() => agregarAMazo(c)} disabled={agregandoMazoId === c.id}
                        style={{ border: `1px solid ${COLORS.violeta}88`, color: COLORS.violeta }}
                        className="rounded-lg py-1 text-[11px] font-semibold flex items-center justify-center gap-1">
                        <Layers size={11} /> {agregandoMazoId === c.id ? "Agregando..." : "Agregar a mazo"}
                      </button>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      )}
    </div>
  );
}

export default function EncuentraCartas() {
  const [view, setView] = useState("search");
  const [query, setQuery] = useState("");
  // Qué TCG le interesa ver (botón en el inicio): se guarda solo en este
  // dispositivo (localStorage), igual que el tema — no requiere sesión ni
  // columna nueva en la base de datos. "todos" no filtra nada.
  const [tcgFiltro, setTcgFiltro] = useState(() => localStorage.getItem("ec_tcg_filtro") || "todos");
  useEffect(() => { localStorage.setItem("ec_tcg_filtro", tcgFiltro); }, [tcgFiltro]);
  const pasaFiltroTcg = (item) => tcgFiltro === "todos" || item.tcg === tcgFiltro;
  const [session, setSession] = useState(null);
  const [perfil, setPerfil] = useState(null);
  // Se pone en true cuando ya terminamos de buscar/crear el perfil de la sesión
  // actual — así distinguimos "todavía cargando" de "de verdad no tiene perfil"
  // (este segundo caso pasa tras un login social nuevo) sin mostrar el modal
  // de completar registro de más.
  const [perfilChecked, setPerfilChecked] = useState(false);
  const [showAccountModal, setShowAccountModal] = useState(false);
  const [confirmarInfo, setConfirmarInfo] = useState(null); // {tokenHash, tipo} del link "Confirma tu cuenta"
  const [logoError, setLogoError] = useState(false);
  const [showDrawer, setShowDrawer] = useState(false);
  const [showOnboarding, setShowOnboarding] = useState(false);
  // Para no saturar a alguien que apenas llega: mientras no haya visto el
  // tutorial (mismo criterio que showOnboarding), la pantalla de inicio
  // condensa los banners promocionales y prioriza una guía corta de 3 pasos.
  // Se calcula una sola vez al montar para que no "salte" el layout a media
  // sesión si abre el tutorial manualmente después.
  const [esVisitanteNuevo] = useState(() => {
    try { return !localStorage.getItem(ONBOARDING_SEEN_KEY); } catch { return false; }
  });
  const [, setTemaVersion] = useState(0);
  const [chatContext, setChatContext] = useState(null);
  const [mostrarBuscarCarta, setMostrarBuscarCarta] = useState(false);
  const [busquedasVersion, setBusquedasVersion] = useState(0); // bump para refrescar el carrusel tras publicar una búsqueda
  const [adminStash, setAdminStash] = useState(() => {
    const s = localStorage.getItem("ec_session_admin_stash");
    return s ? JSON.parse(s) : null;
  });

  // ---- Carrito: guarda las cartas/sellado que alguien quiere pedir, para
  // luego mandar un solo mensaje a cada vendedor en vez de uno por uno. Vive
  // solo en este dispositivo (localStorage), como el tema o el filtro de TCG —
  // no necesita sincronizarse entre dispositivos ni sobrevivir en el servidor.
  const [carrito, setCarrito] = useState(() => {
    try { return JSON.parse(localStorage.getItem("ec_carrito") || "[]"); } catch { return []; }
  });
  useEffect(() => { localStorage.setItem("ec_carrito", JSON.stringify(carrito)); }, [carrito]);

  const enElCarrito = (tabla, id) => carrito.some((it) => it.tabla === tabla && it.id === id);

  const agregarAlCarrito = (item) => {
    if (!session) { setShowAccountModal(true); return; }
    setCarrito((prev) => (prev.some((it) => it.tabla === item.tabla && it.id === item.id) ? prev : [...prev, item]));
  };

  const quitarDelCarrito = (tabla, id) => setCarrito((prev) => prev.filter((it) => !(it.tabla === tabla && it.id === id)));

  // Cuando sb()/sbWrite() renuevan la sesión sola (el token expiró), nos enteramos aquí.
  useEffect(() => {
    setOnSesionRefrescada((nueva) => setSession(nueva));
    return () => { setOnSesionRefrescada(null); };
  }, []);

  // Para poder incluir quién estaba conectado si algo truena (reportarError).
  useEffect(() => {
    setUidActual(session?.user?.id || null);
  }, [session]);

  const abrirChat = (otherId, otherNombre, contexto, otherWhatsapp, otherFacebook, otherAvatar) => {
    if (!session) { setShowAccountModal(true); return; }
    if (!otherId) return; // sin cuenta vinculada, no se puede chatear todavía
    if (otherId === session.user.id) return; // no chatear contigo mismo
    setChatContext({ otherId, otherNombre, contexto, otherWhatsapp, otherFacebook, otherAvatar });
  };

  // Si volvemos de Mercado Pago (plan, boost o suscripción), refrescamos el perfil
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    if ((params.get("pago") || params.get("plan") || params.get("boost")) && session) {
      cargarOCrearPerfil(session);
    }
  }, [session]);

  // Link "Confirma tu cuenta" del correo (?confirmar=1&token_hash=...&type=...).
  // Ver el comentario de authVerifyOtp() en lib/supabase.js: a propósito NO se
  // confirma solo con que esta página cargue, solo con el clic del modal.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const tokenHash = params.get("token_hash");
    if (params.get("confirmar") && tokenHash) {
      setConfirmarInfo({ tokenHash, tipo: params.get("type") || "signup" });
    }
  }, []);

  const confirmarCorreoConfirmado = (s) => {
    setConfirmarInfo(null);
    const url = new URL(window.location.href);
    url.searchParams.delete("confirmar"); url.searchParams.delete("token_hash"); url.searchParams.delete("type");
    window.history.replaceState({}, "", url.toString());
    handleAuthed(s, { esNuevo: true });
  };

  // Restaurar sesión guardada al abrir la app
  useEffect(() => {
    const saved = localStorage.getItem("ec_session");
    if (saved) {
      const s = JSON.parse(saved);
      setSession(s);
      cargarOCrearPerfil(s);
    }
  }, []);

  // Si venimos de vuelta de un login social (Google/Facebook), Supabase nos
  // regresa aquí con los tokens en el fragmento de la URL en vez de una sesión
  // guardada. Los leemos una sola vez (leerSesionDeUrl limpia el hash).
  useEffect(() => {
    const tokens = leerSesionDeUrl();
    if (!tokens) return;
    obtenerUsuarioDeToken(tokens.access_token)
      .then((user) => {
        const s = { access_token: tokens.access_token, refresh_token: tokens.refresh_token, user };
        localStorage.setItem("ec_session", JSON.stringify(s));
        setSession(s);
        // Si ya tenía cuenta (Google de alguien que ya se había
        // registrado antes), cargarOCrearPerfil encuentra su perfil y
        // esNuevo sale false -- no hace nada más. Si es la primera vez
        // que entra con Google y su tipo de cuenta no viene en
        // user_metadata (nunca lo trae Google), no se crea nada aquí
        // todavía -- se muestra CompletarPerfilOAuthModal más abajo en
        // el render, y ES SU onCreado el que de verdad dispara
        // procesarNuevoRegistro para una cuenta nueva de Google.
        cargarOCrearPerfil(s).then(({ esNuevo } = {}) => { if (esNuevo) procesarNuevoRegistro(s); });
      })
      .catch(() => {});
  }, []);

  // Tutorial de bienvenida: se muestra una sola vez, la primera vez que alguien
  // abre la web (con o sin cuenta); se puede volver a ver desde el menú lateral.
  useEffect(() => {
    try {
      if (!localStorage.getItem(ONBOARDING_SEEN_KEY)) setShowOnboarding(true);
    } catch {}
  }, []);

  // Trae el perfil de la persona; si no existe (primer inicio de sesión tras confirmar su correo),
  // lo crea usando los datos que guardamos al momento del registro.
  // Regresa { perfil, esNuevo } (además de dejar el state de siempre) --
  // esNuevo (true solo cuando esta llamada fue la que creó el renglón de
  // perfiles) es lo que necesita procesarNuevoRegistro para saber si debe
  // acreditar un referido/campaña pendiente en el caso de alguien que
  // inicia sesión ya confirmado sin pasar por el flujo normal de signup.
  const cargarOCrearPerfil = async (s) => {
    try {
      const rows = await sb(`perfiles?select=*&id=eq.${s.user.id}`, s);
      let p = rows[0];
      let creoNuevo = false;
      if (!p && s.user.user_metadata?.tipo) {
        const creado = await crearConSlugUnico("perfiles", {
          id: s.user.id,
          tipo: s.user.user_metadata.tipo,
          nombre: s.user.user_metadata.nombre,
          telefono: s.user.user_metadata.telefono || null,
          whatsapp: s.user.user_metadata.whatsapp || null,
          facebook: s.user.user_metadata.facebook || null,
          avatar_url: s.user.user_metadata.avatar_url || randomPokemonAvatar(),
          email: s.user.email || null,
        }, s.user.user_metadata.nombre, s, "usuario");
        p = Array.isArray(creado) ? creado[0] : creado;
        creoNuevo = !!p;
        // Mismo caso que en AccountModal.handleSignUp: si tuvo que
        // confirmar su correo antes de tener sesión, la tienda se crea
        // hasta ahora (primer login), con los datos que guardamos en
        // user_metadata al registrarse.
        if (p && s.user.user_metadata.tipo === "tienda") {
          await crearConSlugUnico("tiendas", {
            nombre: s.user.user_metadata.nombre,
            perfil_id: s.user.id,
            direccion: s.user.user_metadata.direccion || null,
            zona: s.user.user_metadata.zona || null,
            telefono: s.user.user_metadata.telefono || null,
            sin_local: !!s.user.user_metadata.sin_local || !s.user.user_metadata.direccion,
          }, s.user.user_metadata.nombre, s, "tienda").catch(() => {});
        }
      }
      setPerfil(p || null);
      return { perfil: p || null, esNuevo: creoNuevo };
    } catch {
      setPerfil(null);
      return { perfil: null, esNuevo: false };
    } finally {
      setPerfilChecked(true);
    }
  };

  // Se llama una sola vez, justo cuando se confirma que una cuenta es
  // NUEVA (sin importar el camino: correo directo, confirmar correo y
  // volver, Google, o iniciar sesión ya confirmado -- ver los 3 llamados
  // de más abajo). Acredita el link de referido de siempre (+2 boletos a
  // quien invitó, migración 051) y/o el link de campaña de un sorteo
  // exclusivo (1 boleto plano, migración 077) si había alguno pendiente
  // en sessionStorage -- ambos best-effort: un sorteo/código que ya no
  // existe no debe romper el registro de la cuenta nueva.
  const procesarNuevoRegistro = (s) => {
    let veniaDeSorteo = false;
    try {
      const pendienteRef = JSON.parse(sessionStorage.getItem("ec_referido_pendiente") || "null");
      sessionStorage.removeItem("ec_referido_pendiente");
      if (pendienteRef?.sorteoId && pendienteRef?.refPerfilId && pendienteRef.refPerfilId !== s.user.id) {
        veniaDeSorteo = true;
        sbWrite("POST", "sorteo_referidos", { sorteo_id: pendienteRef.sorteoId, referente_perfil_id: pendienteRef.refPerfilId, nuevo_perfil_id: s.user.id }, s).catch(() => {});
      }
    } catch {}
    try {
      const pendienteCampana = JSON.parse(sessionStorage.getItem("ec_campana_pendiente") || "null");
      sessionStorage.removeItem("ec_campana_pendiente");
      if (pendienteCampana?.codigo) {
        veniaDeSorteo = true;
        sbWrite("POST", "rpc/sorteo_unirse_por_campana", { p_codigo: pendienteCampana.codigo }, s).catch(() => {});
      }
    } catch {}
    // Si venía de un link de sorteo, la dejamos en esa vista (ya la puso
    // el efecto de parseo de URL) en vez de mandarla a Ayuda -- así
    // alguien que se acaba de registrar por el link del video cae de
    // vuelta en su sorteo, no en una pantalla genérica.
    if (!veniaDeSorteo) setView("ayuda");
  };

  const handleAuthed = (s, { esNuevo } = {}) => {
    setSession(s);
    setShowAccountModal(false);
    cargarOCrearPerfil(s).then(({ esNuevo: creoNuevo } = {}) => {
      if (esNuevo || creoNuevo) procesarNuevoRegistro(s);
    });
  };

  const handleLogout = () => {
    localStorage.removeItem("ec_session");
    localStorage.removeItem("ec_session_admin_stash");
    setAdminStash(null);
    setSession(null);
    setPerfil(null);
    setPerfilChecked(false);
  };

  // Un admin puede "entrar" a un sub-perfil que administra (ver AdminPanel > Sub-perfiles):
  // guardamos su propia sesión aparte para poder regresar a ella después.
  const entrarComoSubperfil = (subSession) => {
    localStorage.setItem("ec_session_admin_stash", JSON.stringify(session));
    localStorage.setItem("ec_session", JSON.stringify(subSession));
    setAdminStash(session);
    setSession(subSession);
    cargarOCrearPerfil(subSession);
    setView("myMarket");
  };

  const volverAMiCuentaAdmin = () => {
    if (!adminStash) return;
    localStorage.setItem("ec_session", JSON.stringify(adminStash));
    localStorage.removeItem("ec_session_admin_stash");
    setSession(adminStash);
    cargarOCrearPerfil(adminStash);
    setAdminStash(null);
    setView("admin");
  };

  const [tiendas, setTiendas] = useState([]);
  const [loadingTiendas, setLoadingTiendas] = useState(true);
  const [errorTiendas, setErrorTiendas] = useState(null);

  // Qué TCG vende cada tienda (a partir de su inventario/sellado real), para
  // poder filtrar el Directorio por TCG igual que Buscar/Mercado.
  const [tiendasTcgMap, setTiendasTcgMap] = useState({});
  useEffect(() => {
    Promise.all([
      sb("inventario_tienda?select=tienda_id,tcg").catch(() => []),
      // sellado_tienda.tcg es columna nueva (migración 044) — si todavía no se
      // corrió, esta consulta falla sola sin tumbar el mapa de inventario.
      sb("sellado_tienda?select=tienda_id,tcg").catch(() => []),
    ]).then(([inv, sel]) => {
      const mapa = {};
      [...inv, ...sel].forEach((r) => {
        if (!mapa[r.tienda_id]) mapa[r.tienda_id] = new Set();
        mapa[r.tienda_id].add(r.tcg);
      });
      setTiendasTcgMap(mapa);
    }).catch(() => {});
  }, []);

  // ---- Directorio: filtro por zona + tienda más cercana (Zafiro+) ----
  const [filtroZona, setFiltroZona] = useState("");
  const [ubicacionUsuario, setUbicacionUsuario] = useState(null); // { lat, lng }
  const [buscandoUbicacion, setBuscandoUbicacion] = useState(false);
  const [errorUbicacion, setErrorUbicacion] = useState(null);

  const usarMiUbicacion = () => {
    if (!navigator.geolocation) { setErrorUbicacion("Tu navegador no soporta geolocalización."); return; }
    setBuscandoUbicacion(true); setErrorUbicacion(null);
    navigator.geolocation.getCurrentPosition(
      (pos) => { setUbicacionUsuario({ lat: pos.coords.latitude, lng: pos.coords.longitude }); setBuscandoUbicacion(false); },
      () => { setErrorUbicacion("No pudimos obtener tu ubicación (¿diste permiso en el navegador?)."); setBuscandoUbicacion(false); },
      { enableHighAccuracy: true, timeout: 10000 }
    );
  };

  const zonasDisponibles = [...new Set(tiendas.map((t) => t.zona).filter(Boolean))].sort();
  const tiendasConDistancia = tiendas.map((t) => ({
    ...t,
    _distanciaKm: ubicacionUsuario && t.lat != null && t.lng != null ? distanciaKm(ubicacionUsuario.lat, ubicacionUsuario.lng, t.lat, t.lng) : null,
  }));
  const tiendasFiltradas = tiendasConDistancia
    .filter((t) => !filtroZona || t.zona === filtroZona)
    .filter((t) => tcgFiltro === "todos" || tiendasTcgMap[t.id]?.has(tcgFiltro))
    .sort((a, b) => {
      if (!ubicacionUsuario) return 0;
      if (a._distanciaKm == null && b._distanciaKm == null) return 0;
      if (a._distanciaKm == null) return 1;
      if (b._distanciaKm == null) return -1;
      return a._distanciaKm - b._distanciaKm;
    });
  const tiendaMasCercana = ubicacionUsuario ? tiendasFiltradas.find((t) => t._distanciaKm != null) : null;

  const [searchResults, setSearchResults] = useState({ tiendas: [], mercado: [], sellado: [] });
  const [searching, setSearching] = useState(false);
  const [searchError, setSearchError] = useState(null);

  const [selectedStore, setSelectedStore] = useState(null);
  const [selectedPerfilId, setSelectedPerfilId] = useState(null);
  const [selectedSorteoId, setSelectedSorteoId] = useState(null);
  const [selectedSubastaId, setSelectedSubastaId] = useState(null);
  const [selectedCarpetaPublicaId, setSelectedCarpetaPublicaId] = useState(null);
  const [selectedWishlistPerfilId, setSelectedWishlistPerfilId] = useState(null);
  const [vistaAntesDePerfil, setVistaAntesDePerfil] = useState("search");
  const [vistaAntesLegal, setVistaAntesLegal] = useState("search");
  const irALegal = (id) => { setVistaAntesLegal(view); setView(id); };
  const [storeInventory, setStoreInventory] = useState([]);
  const [storeSellado, setStoreSellado] = useState([]);
  const [loadingStoreDetail, setLoadingStoreDetail] = useState(false);
  const [storeResenas, setStoreResenas] = useState([]);
  const [storeVentasCompletadas, setStoreVentasCompletadas] = useState(0);
  const [storeDestellos, setStoreDestellos] = useState(0);
  const [storeSeguidores, setStoreSeguidores] = useState(0);
  const [storeCarpetas, setStoreCarpetas] = useState([]);

  const [market, setMarket] = useState([]);
  const [loadingMarket, setLoadingMarket] = useState(false);
  // Cartas sueltas publicadas por tiendas (inventario_tienda) -- se mezclan
  // con "market" (mercado_listings, vendedores individuales) para que
  // "Mercado entre usuarios" también muestre lo que sube una tienda, igual
  // que ya hacían "Buscar" y la vitrina de inicio (ver conMarketNormalizado).
  const [marketTiendas, setMarketTiendas] = useState([]);
  const [loadingMarketTiendas, setLoadingMarketTiendas] = useState(false);
  const [tipoMercadoTab, setTipoMercadoTab] = useState("todos"); // todos | carta | sellado | accesorio

  // Filtros de precio/idioma/estado/zona -- se usan tanto en "Mercado entre
  // usuarios" como en "Buscar" (mismo panel, mismo estado, para que el
  // filtro se sienta como una sola cosa en toda la app en vez de dos
  // paneles distintos). Aparte del filtro por tipo y por TCG (selector
  // global, pasaFiltroTcg). Idioma/estado solo aplican a cartas sueltas; si
  // están activos, un sellado/accesorio (que no tienen esos campos) queda
  // excluido -- tiene sentido, porque filtrar por idioma solo importa si
  // estás buscando cartas.
  const [filtrosAbiertos, setFiltrosAbiertos] = useState(false);
  const [filtros, setFiltros] = useState({ precioMin: "", precioMax: "", idioma: "", condicion: "", zona: "" });
  const filtrosActivos = Object.values(filtros).some(Boolean);
  // La zona vive en columnas distintas según de dónde viene el resultado:
  // plana en mercado_listings (item.zona), anidada bajo tiendas en
  // inventario_tienda/sellado_tienda (item.tiendas.zona).
  const zonaDe = (item) => item.zona || item.tiendas?.zona || "";
  const pasaFiltros = (item) => {
    const f = filtros;
    if (f.precioMin && Number(item.precio) < Number(f.precioMin)) return false;
    if (f.precioMax && Number(item.precio) > Number(f.precioMax)) return false;
    if (f.idioma && item.idioma !== f.idioma) return false;
    if (f.condicion && item.condicion !== f.condicion) return false;
    if (f.zona && zonaDe(item) !== f.zona) return false;
    return true;
  };
  // Mezcla mercado_listings (vendedores individuales) con inventario_tienda
  // (cartas sueltas de una tienda) en una sola lista para "Mercado entre
  // usuarios" -- inventario_tienda no trae los mismos campos "planos" que
  // mercado_listings (el nombre/avatar del vendedor vive anidado bajo
  // "tiendas", no hay "tipo" porque siempre es carta, etc.), así que se
  // normaliza aquí una sola vez en vez de repetir el branching en cada
  // lugar del JSX que muestra al vendedor.
  const marketNormalizado = (rowsIndividuales, rowsTiendas) => [
    ...rowsIndividuales.map((r) => ({
      ...r, _esTienda: false, _tabla: "mercado_listings",
      _vendedorId: r.perfil_id, _vendedorNombre: r.perfiles?.nombre || "Usuario",
      _vendedorAvatar: r.perfiles?.avatar_url, _vendedorWhatsapp: r.perfiles?.whatsapp, _vendedorFacebook: r.perfiles?.facebook,
    })),
    ...rowsTiendas.map((r) => ({
      ...r, tipo: r.tipo || "carta", _esTienda: true, _tabla: "inventario_tienda",
      _vendedorId: r.tiendas?.perfil_id, _vendedorNombre: r.tiendas?.nombre || "Tienda",
      _vendedorAvatar: r.tiendas?.perfiles?.avatar_url, _vendedorWhatsapp: null, _vendedorFacebook: null,
      perfiles: r.tiendas?.perfiles, // para que PlanBadge siga funcionando igual que con mercado_listings
    })),
  ];
  // Orden de precio: aparte de los filtros de arriba (esos ocultan resultados,
  // esto solo cambia el orden en el que se muestran) -- por default se respeta
  // el orden con los boosts primero (conBoostPrimero).
  const [ordenResultados, setOrdenResultados] = useState(""); // "" | "precio_asc" | "precio_desc"
  const ordenarPorPrecio = (arr) => {
    if (ordenResultados === "precio_asc") return [...arr].sort((a, b) => Number(a.precio) - Number(b.precio));
    if (ordenResultados === "precio_desc") return [...arr].sort((a, b) => Number(b.precio) - Number(a.precio));
    return arr;
  };
  const [news, setNews] = useState([]);
  const [loadingNews, setLoadingNews] = useState(false);
  const [inicioTienda, setInicioTienda] = useState([]);
  const [loadingInicio, setLoadingInicio] = useState(false);

  // Carga inicial: lista de tiendas reales
  useEffect(() => {
    setLoadingTiendas(true);
    sb("tiendas?select=*,perfiles!perfil_id(plan,plan_vence,instagram,google_maps_url,sitio_web,avatar_url,diamante_desde,created_at,tiempo_respuesta_promedio_minutos,tiempo_respuesta_conteo),verificaciones_tienda(estado)&order=nombre.asc")
      .then(setTiendas)
      .catch((e) => setErrorTiendas(e.message))
      .finally(() => setLoadingTiendas(false));
  }, []);

  // Búsqueda en vivo (tiendas + mercado + producto sellado)
  useEffect(() => {
    if (!query.trim()) {
      setSearchResults({ tiendas: [], mercado: [], sellado: [] });
      return;
    }
    const q = encodeURIComponent(pgLikeValor(query));
    const filtroCartaSet = filtroPalabrasCartaOSet(query);
    // mercado_listings también incluye accesorios (tipo="accesorio") — se buscan
    // además por sus etiquetas_texto, para que "sylveon" encuentre un accesorio
    // con esa palabra clave aunque no sea una carta (ver migración 046).
    const filtroMercado = filtroPalabrasCartaOSet(query, "etiquetas_texto");
    setSearching(true);
    setSearchError(null);
    const t = setTimeout(() => {
      Promise.all([
        sb(`inventario_tienda?select=*,tiendas(nombre,zona,direccion,telefono,perfil_id,perfiles!perfil_id(plan,plan_vence,avatar_url))&${filtroCartaSet}&en_venta=eq.true&order=precio.asc`),
        sb(`mercado_listings?select=*,perfiles(nombre,whatsapp,facebook,plan,plan_vence,avatar_url),buzon_tienda:buzon_tienda_id(nombre)&${filtroMercado}&en_venta=eq.true&order=precio.asc`),
        sb(`sellado_tienda?select=*,tiendas(nombre,zona,direccion,telefono,perfil_id,perfiles!perfil_id(plan,plan_vence,avatar_url))&producto=ilike.${q}&order=precio.asc`),
      ])
        .then(([inv, merc, sel]) => setSearchResults({ tiendas: conBoostPrimero(inv), mercado: conBoostPrimero(merc), sellado: conBoostPrimero(sel) }))
        .catch((e) => { setSearchResults({ tiendas: [], mercado: [], sellado: [] }); setSearchError(e.message); })
        .finally(() => setSearching(false));
    }, 350); // pequeña espera para no saturar mientras escribes
    return () => clearTimeout(t);
  }, [query]);

  // Mercado y noticias, al entrar a esas pestañas (y también para la vitrina de inicio)
  useEffect(() => {
    const necesitaVitrina = view === "search" && !query.trim();
    if (necesitaVitrina && market.length === 0) {
      setLoadingMarket(true);
      sb("mercado_listings?select=*,perfiles(nombre,whatsapp,facebook,plan,plan_vence,avatar_url),buzon_tienda:buzon_tienda_id(nombre)&en_venta=eq.true&order=created_at.desc").then((rows) => setMarket(conBoostPrimero(rows))).finally(() => setLoadingMarket(false));
    }
    if (necesitaVitrina && marketTiendas.length === 0) {
      setLoadingMarketTiendas(true);
      sb("inventario_tienda?select=*,tiendas(nombre,zona,perfil_id,perfiles!perfil_id(plan,plan_vence,avatar_url))&en_venta=eq.true&order=created_at.desc")
        .then((rows) => setMarketTiendas(conBoostPrimero(rows)))
        .finally(() => setLoadingMarketTiendas(false));
    }
    if ((view === "news" || necesitaVitrina) && news.length === 0) {
      setLoadingNews(true);
      sb("noticias?select=*,tiendas(nombre,perfiles!perfil_id(avatar_url))&publicado=eq.true&order=fecha_publicacion.desc").then(setNews).finally(() => setLoadingNews(false));
    }
    if (necesitaVitrina && inicioTienda.length === 0) {
      setLoadingInicio(true);
      sb("inventario_tienda?select=*,tiendas(nombre,zona,perfil_id,perfiles!perfil_id(plan,plan_vence,avatar_url))&en_venta=eq.true&order=created_at.desc&limit=10")
        .then((rows) => setInicioTienda(conBoostPrimero(rows)))
        .finally(() => setLoadingInicio(false));
    }
    if (view === "inbox" && session) {
      cargarInbox();
    }
  }, [view]);

  const [conversaciones, setConversaciones] = useState([]);
  const [loadingInbox, setLoadingInbox] = useState(false);
  const [tabInbox, setTabInbox] = useState("mensajes"); // "mensajes" | "papelera"
  const [papelera, setPapelera] = useState([]);
  const [loadingPapelera, setLoadingPapelera] = useState(false);

  // Numerito del botón flotante de chats -- independiente de haber
  // visitado la bandeja alguna vez (cargarInbox solo corre al entrar a
  // "inbox"), así que se carga aparte desde que hay sesión. cargarInbox
  // también lo refresca de gratis con lo que ya trae (ver abajo), y
  // ChatModal lo vuelve a pedir en cuanto marca una conversación como leída.
  const [mensajesNoLeidos, setMensajesNoLeidos] = useState(0);
  const cargarMensajesNoLeidos = () => {
    if (!session) { setMensajesNoLeidos(0); return; }
    sb(`mensajes?select=id&para_perfil_id=eq.${session.user.id}&leido=eq.false`, session)
      .then((rows) => setMensajesNoLeidos(rows.length))
      .catch(() => {});
  };
  useEffect(() => { cargarMensajesNoLeidos(); }, [session?.user?.id]);

  // Push de mensajes nuevos: antes `activarPush` solo se ofrecía dentro de
  // Wishlist Premium (plan pago), así que un usuario gratis jamás terminaba
  // con una fila en push_subscriptions y nunca podía recibir el push de
  // "te llegó un mensaje" (ver api/alertas/verificar.js). Se ofrece también
  // aquí, en la bandeja de Mensajes, disponible para cualquiera con sesión.
  const [pushChatOk, setPushChatOk] = useState(() => typeof Notification !== "undefined" && Notification.permission === "granted");
  const [activandoPushChat, setActivandoPushChat] = useState(false);
  const [errorPushChat, setErrorPushChat] = useState(null);
  const handleActivarPushChat = async () => {
    setActivandoPushChat(true); setErrorPushChat(null);
    try { await activarPush(session); setPushChatOk(true); }
    catch (e) { setErrorPushChat(e.message); }
    finally { setActivandoPushChat(false); }
  };

  const cargarPapelera = () => {
    setLoadingPapelera(true);
    const uid = session.user.id;
    sb(`mensajes_papelera?select=*,otro:otro_perfil_id(nombre,avatar_url)&perfil_id=eq.${uid}&definitivo=eq.false&order=eliminado_en.desc`, session)
      .then(setPapelera)
      .catch(() => setPapelera([]))
      .finally(() => setLoadingPapelera(false));
  };

  const cargarInbox = () => {
    setLoadingInbox(true);
    const uid = session.user.id;
    Promise.all([
      sb(
        `mensajes?select=*,remitente:de_perfil_id(nombre,whatsapp,facebook,avatar_url),destinatario:para_perfil_id(nombre,whatsapp,facebook,avatar_url)&or=(de_perfil_id.eq.${uid},para_perfil_id.eq.${uid})&order=created_at.desc`,
        session
      ),
      sb(`mensajes_papelera?select=otro_perfil_id,contexto&perfil_id=eq.${uid}`, session).catch(() => []),
    ])
      .then(([rows, papeleraRows]) => {
        // Las conversaciones que ya moví a la papelera no se muestran en la bandeja.
        const enPapelera = new Set((papeleraRows || []).map((p) => `${p.otro_perfil_id}::${p.contexto}`));
        // Agrupamos por conversación: mismo interlocutor + mismo tema (contexto)
        const grupos = new Map();
        rows.forEach((m) => {
          const soyRemitente = m.de_perfil_id === uid;
          const otherId = soyRemitente ? m.para_perfil_id : m.de_perfil_id;
          const otherPerfil = soyRemitente ? m.destinatario : m.remitente;
          const key = `${otherId}::${m.contexto}`;
          if (enPapelera.has(key)) return;
          if (!grupos.has(key)) {
            grupos.set(key, {
              otherId,
              otherNombre: otherPerfil?.nombre || "Usuario",
              otherWhatsapp: otherPerfil?.whatsapp,
              otherFacebook: otherPerfil?.facebook,
              otherAvatar: otherPerfil?.avatar_url,
              contexto: m.contexto,
              ultimoMensaje: m.texto,
              fecha: m.created_at,
            });
          }
        });
        setConversaciones(Array.from(grupos.values()));
        setMensajesNoLeidos(rows.filter((m) => m.para_perfil_id === uid && !m.leido).length);
      })
      .finally(() => setLoadingInbox(false));
    cargarPapelera();
  };

  const moverAPapelera = async (otherId, contexto) => {
    try {
      await sbWrite("POST", "mensajes_papelera", { perfil_id: session.user.id, otro_perfil_id: otherId, contexto }, session);
    } catch {} // si ya estaba en la papelera (duplicado), no pasa nada
    cargarInbox();
  };

  const restaurarDePapelera = async (otherId, contexto) => {
    try {
      await sbWrite("DELETE", `mensajes_papelera?perfil_id=eq.${session.user.id}&otro_perfil_id=eq.${otherId}&contexto=eq.${encodeURIComponent(contexto)}`, {}, session);
    } catch {}
    cargarInbox();
  };

  // Cada perfil y tienda tiene su propio link (?u=<slug> / ?tienda=<slug>),
  // para compartir en redes, Google Business Profile, etc. en vez de que
  // todos compartan la misma URL genérica. Esta función limpia los demás
  // parámetros de deep-link (evita que se arrastren viejos) y pone los que
  // correspondan a la vista nueva.
  const actualizarUrlCompartible = (params) => {
    try {
      const u = new URL(window.location.href);
      ["listing", "tabla", "u", "tienda", "sorteo", "ref", "c", "subasta", "carpeta", "wishlist"].forEach((k) => u.searchParams.delete(k));
      Object.entries(params || {}).forEach(([k, v]) => { if (v) u.searchParams.set(k, v); });
      // replaceState, no pushState: esta función solo mantiene la URL
      // visible/compartible correcta -- quien crea entradas reales del
      // historial (para que "atrás" funcione) es el efecto de navegación
      // más abajo, una sola vez por cambio real de pantalla.
      window.history.replaceState({}, "", u);
    } catch {}
  };

  const openStore = (store) => {
    setSelectedStore(store);
    setView("storeDetail");
    setLoadingStoreDetail(true);
    setStoreResenas([]); setStoreVentasCompletadas(0); setStoreDestellos(0); setStoreSeguidores(0); setStoreCarpetas([]);
    actualizarUrlCompartible(store.slug ? { tienda: store.slug } : {});
    Promise.all([
      sb(`inventario_tienda?select=*&tienda_id=eq.${store.id}`),
      sb(`sellado_tienda?select=*&tienda_id=eq.${store.id}`),
    ])
      .then(([inv, sell]) => { setStoreInventory(conBoostPrimero(inv)); setStoreSellado(conBoostPrimero(sell)); })
      .finally(() => setLoadingStoreDetail(false));
    sb(`carpetas?select=id,nombre,columnas,filas&tienda_id=eq.${store.id}&order=created_at.desc`).then(setStoreCarpetas).catch(() => {});
    if (store.perfil_id) {
      sb(`resenas?select=*,autor:autor_perfil_id(nombre,avatar_url)&objetivo_perfil_id=eq.${store.perfil_id}&order=created_at.desc&limit=20`).then(setStoreResenas).catch(() => {});
      sb(`ventas?select=id&vendedor_perfil_id=eq.${store.perfil_id}&estado=eq.confirmada`).then((filas) => setStoreVentasCompletadas(filas.length)).catch(() => {});
      sb(`destellos_movimientos?select=cantidad&perfil_id=eq.${store.perfil_id}`).then((filas) => setStoreDestellos(filas.reduce((s, m) => s + m.cantidad, 0))).catch(() => {});
      sb(`seguidores?select=id&seguido_perfil_id=eq.${store.perfil_id}`).then((filas) => setStoreSeguidores(filas.length)).catch(() => {});
    }
  };

  const cerrarStore = () => {
    setView("directory");
    actualizarUrlCompartible({});
  };

  const verPerfil = (perfilId) => {
    if (!perfilId) return;
    setVistaAntesDePerfil(view);
    setSelectedPerfilId(perfilId);
    setView("perfilPublico");
    actualizarUrlCompartible({}); // el slug se agrega solo cuando PerfilPublicoView termine de cargarlo
  };

  const cerrarPerfil = () => {
    setView(vistaAntesDePerfil);
    actualizarUrlCompartible({});
  };

  // Ficha de detalle de una publicación (carta o sellado): abre en grande la
  // imagen, precio de referencia en vivo, vendedor y ofertas/comentarios. Se
  // puede llegar por click en cualquier tarjeta o por un link compartido
  // (?listing=<id>&tabla=<tabla>).
  const [selectedListing, setSelectedListing] = useState(null); // { id, tabla }
  const [vistaAntesDeDetalle, setVistaAntesDeDetalle] = useState("search");

  const abrirDetalle = (id, tabla) => {
    if (!id || !tabla) return;
    setVistaAntesDeDetalle(view === "cartaDetalle" ? vistaAntesDeDetalle : view);
    setSelectedListing({ id, tabla });
    setView("cartaDetalle");
    actualizarUrlCompartible({ listing: id, tabla });
  };

  const cerrarDetalle = () => {
    setSelectedListing(null);
    setView(vistaAntesDeDetalle);
    actualizarUrlCompartible({});
  };

  const abrirSorteo = (id) => {
    setSelectedSorteoId(id);
    setView("sorteoDetalle");
    actualizarUrlCompartible({ sorteo: id });
  };

  const abrirSubasta = (id) => {
    setSelectedSubastaId(id);
    setView("subastaDetalle");
    actualizarUrlCompartible({ subasta: id });
  };

  // Al abrir la app con un link compartido (de una publicación, un perfil o
  // una tienda), la abrimos directo.
  useEffect(() => {
    const params = new URLSearchParams(window.location.search);
    const listing = params.get("listing");
    const tabla = params.get("tabla");
    const uSlug = params.get("u");
    const tiendaSlug = params.get("tienda");
    const sorteoId = params.get("sorteo");
    const refPerfilId = params.get("ref");
    const campanaCodigo = params.get("c");
    const subastaId = params.get("subasta");
    const carpetaId = params.get("carpeta");
    const wishlistSlug = params.get("wishlist");
    // Link de referido de un sorteo (?sorteo=X&ref=Y): se guarda para
    // acreditárselo a quien invitó en cuanto esta visita termine de
    // registrarse (ver procesarNuevoRegistro) -- puede pasar varias
    // pantallas (elige tipo de cuenta, confirma correo, etc.) antes de eso.
    if (sorteoId && refPerfilId) {
      try { sessionStorage.setItem("ec_referido_pendiente", JSON.stringify({ sorteoId, refPerfilId })); } catch {}
    }
    // Link de campaña de un sorteo EXCLUSIVO (?sorteo=X&c=CODIGO, ver
    // migración 077): mecánica separada del referido de arriba -- esta
    // guarda el código para que, en cuanto haya sesión (cuenta nueva o ya
    // existente), procesarNuevoRegistro/SorteoDetalleView llame
    // rpc/sorteo_unirse_por_campana y entre con 1 boleto plano.
    if (sorteoId && campanaCodigo) {
      try { sessionStorage.setItem("ec_campana_pendiente", JSON.stringify({ sorteoId, codigo: campanaCodigo })); } catch {}
    }
    if (listing && tabla) {
      setSelectedListing({ id: listing, tabla });
      setView("cartaDetalle");
    } else if (uSlug) {
      sb(`perfiles?select=id&slug=eq.${encodeURIComponent(uSlug)}`)
        .then((rows) => { if (rows[0]) verPerfil(rows[0].id); })
        .catch(() => {});
    } else if (tiendaSlug) {
      sb(`tiendas?select=*,perfiles!perfil_id(plan,plan_vence,instagram,google_maps_url,sitio_web,avatar_url,diamante_desde,created_at,tiempo_respuesta_promedio_minutos,tiempo_respuesta_conteo),verificaciones_tienda(estado)&slug=eq.${encodeURIComponent(tiendaSlug)}`)
        .then((rows) => { if (rows[0]) openStore(rows[0]); })
        .catch(() => {});
    } else if (sorteoId) {
      setSelectedSorteoId(sorteoId);
      setView("sorteoDetalle");
    } else if (subastaId) {
      setSelectedSubastaId(subastaId);
      setView("subastaDetalle");
    } else if (carpetaId) {
      setSelectedCarpetaPublicaId(carpetaId);
      setView("carpetaPublica");
    } else if (wishlistSlug) {
      // La wishlist no es una fila con su propio id (es "las cartas quiero
      // de este perfil"), así que el link usa el slug del perfil, igual
      // que ?u=<slug> -- se resuelve a un id antes de abrir la vista.
      sb(`perfiles?select=id&slug=eq.${encodeURIComponent(wishlistSlug)}`)
        .then((rows) => { if (rows[0]) abrirWishlistPublica(rows[0].id); })
        .catch(() => {});
    }
  }, []);

  const abrirCarpetaPublica = (id) => {
    setSelectedCarpetaPublicaId(id);
    setView("carpetaPublica");
    actualizarUrlCompartible({ carpeta: id });
  };

  const abrirWishlistPublica = (perfilId, slug) => {
    setSelectedWishlistPerfilId(perfilId);
    setView("wishlistPublica");
    if (slug) actualizarUrlCompartible({ wishlist: slug });
  };

  const verTiendaDesdePerfil = (tiendaId) => {
    sb(`tiendas?select=*,perfiles!perfil_id(plan,plan_vence,instagram,google_maps_url,sitio_web,avatar_url,diamante_desde,created_at,tiempo_respuesta_promedio_minutos,tiempo_respuesta_conteo),verificaciones_tienda(estado)&id=eq.${tiendaId}`)
      .then((rows) => { if (rows[0]) openStore(rows[0]); });
  };

  // ---- Botón/gesto de "atrás" (navegador y celular) ----
  // La app no usa router -- este efecto + el listener de abajo son todo
  // lo que hace falta para que "atrás" funcione en todas las pantallas
  // de nivel raíz, no solo las que ya tenían link compartible. No toca
  // ninguno de los ~40 sitios que llaman setView -- reacciona a los
  // cambios de view/seleccionados, sin importar quién los causó.
  const snapshotNavegacion = () => ({
    view,
    listingId: selectedListing?.id || null,
    listingTabla: selectedListing?.tabla || null,
    perfilId: selectedPerfilId,
    tiendaId: selectedStore?.id || null,
    sorteoId: selectedSorteoId,
    subastaId: selectedSubastaId,
    carpetaId: selectedCarpetaPublicaId,
    wishlistPerfilId: selectedWishlistPerfilId,
  });

  const restaurandoHistorialRef = useRef(false);
  const montadoNavRef = useRef(false);

  // Cada vez que cambia lo que se está viendo, se agrega una entrada al
  // historial -- así "atrás" siempre tiene algo real que recorrer. La
  // primera vez (montaje) se usa replaceState en vez de pushState, para
  // no duplicar la entrada que el navegador ya trae de por sí. Si el
  // cambio vino de restaurar por popstate (ver abajo), no se vuelve a
  // empujar -- si no, cada "atrás" generaría una entrada nueva hacia
  // adelante en vez de retroceder de verdad.
  useEffect(() => {
    if (restaurandoHistorialRef.current) { restaurandoHistorialRef.current = false; return; }
    try {
      if (!montadoNavRef.current) { montadoNavRef.current = true; window.history.replaceState(snapshotNavegacion(), "", window.location.href); }
      else { window.history.pushState(snapshotNavegacion(), "", window.location.href); }
    } catch {}
  }, [view, selectedListing, selectedPerfilId, selectedStore, selectedSorteoId, selectedSubastaId, selectedCarpetaPublicaId, selectedWishlistPerfilId]);

  // Restaura la pantalla exacta al darle "atrás"/"adelante" (o al gesto
  // de atrás en celular, que dispara el mismo evento) -- reusa las
  // mismas funciones que ya abren cada pantalla desde un link
  // compartido, nunca duplica esa lógica.
  useEffect(() => {
    const onPopState = (e) => {
      restaurandoHistorialRef.current = true;
      const s = e.state;
      if (!s) { setView("search"); return; }
      if (s.listingId && s.listingTabla) abrirDetalle(s.listingId, s.listingTabla);
      else if (s.view === "perfilPublico" && s.perfilId) verPerfil(s.perfilId);
      else if (s.view === "storeDetail" && s.tiendaId) verTiendaDesdePerfil(s.tiendaId);
      else if (s.view === "sorteoDetalle" && s.sorteoId) abrirSorteo(s.sorteoId);
      else if (s.view === "subastaDetalle" && s.subastaId) abrirSubasta(s.subastaId);
      else if (s.view === "carpetaPublica" && s.carpetaId) abrirCarpetaPublica(s.carpetaId);
      else if (s.view === "wishlistPublica" && s.wishlistPerfilId) abrirWishlistPublica(s.wishlistPerfilId);
      else setView(s.view || "search");
    };
    window.addEventListener("popstate", onPopState);
    return () => window.removeEventListener("popstate", onPopState);
  }, []);

  // Esenciales: siempre visibles arriba, máximo 5 para no saturar el
  // encabezado -- las mismas 4 para cualquier persona (comprar es lo que
  // hace todo el mundo) más "Mensajes" si ya inició sesión. Todo lo demás
  // vive en el menú lateral, organizado por pestañas (ver navGrupos) para
  // que siga siendo fácil de encontrar sin ocupar espacio arriba.
  // "Mensajes" ya no vive aquí -- se abre desde el botón flotante de chats
  // (esquina inferior, junto al carrito) para que no dependa de encontrar
  // un ícono arriba. Sigue siendo una vista normal (setView("inbox")), solo
  // cambió cómo se llega a ella.
  const navEsenciales = [
    { id: "search", label: "Inicio", icon: Search },
    { id: "directory", label: "Tiendas", icon: Store },
    { id: "catalogo", label: "Catálogo", icon: BookOpen },
  ];
  // Antes "Mercado" ocupaba este lugar del nav -- se fusionó con Inicio (ver
  // vista "search"), así que el espacio se usa para un CTA vistoso hacia
  // Vender en vez de una pestaña más (mismo routing que el botón del hero).
  const irAVender = () => {
    if (!session) return setShowAccountModal(true);
    setView(perfil?.tipo === "tienda" ? "myStore" : "myMarket");
  };
  // El resto vive en el menú lateral (Drawer), agrupado en pestañas claras
  // (ver Drawer) para que nada se sienta "perdido" ni sature al usuario:
  // "Vender" (acciones de vendedor), "Comunidad" (torneos, mazos, noticias),
  // "Mi cuenta" (beneficios de plan) y "Ayuda". El perfil (editar/cerrar
  // sesión) se queda fuera de las pestañas, siempre visible abajo del todo.
  const navGrupos = [
    {
      id: "vender", label: "Vender", icon: Tag,
      items: [
        ...(perfil?.tipo === "tienda" ? [{ id: "myStore", label: "Mi tienda", icon: Package }] : []),
        ...(perfil?.tipo === "individual" ? [{ id: "myMarket", label: "Vender en el Mercado", icon: Tag }] : []),
        { id: "subastas", label: "Subastas", icon: Gavel },
        ...(session ? [{ id: "comprasVentas", label: "Mis compras y ventas", icon: Star }] : []),
        ...(session ? [{ id: "modoEvento", label: "Modo Evento", icon: Calendar }] : []),
        ...(session ? [{ id: "coleccion", label: "Colección", icon: Layers }] : []),
      ],
    },
    {
      id: "comunidad", label: "Comunidad", icon: Newspaper,
      items: [
        { id: "torneos", label: "Torneos", icon: Calendar },
        { id: "sorteos", label: "Sorteos", icon: Gift },
        { id: "armarMazo", label: "Armar mazo", icon: Layers },
        { id: "competitivo", label: "Competitivo", icon: Trophy },
        { id: "comunidad", label: "Comunidad", icon: Newspaper },
        { id: "news", label: "Noticias", icon: Megaphone },
        { id: "busquedas", label: "Cartas que están buscando", icon: Search },
        ...(session ? [{ id: "siguiendo", label: "Tiendas que sigo", icon: User }] : []),
      ],
    },
    {
      id: "cuenta", label: "Mi cuenta", icon: Sparkles,
      items: [
        ...(session ? [{ id: "alertas", label: "Lista de deseos", icon: Sparkles }] : []),
        ...(session ? [{ id: "recompensas", label: "Recompensas", icon: Sparkles }] : []),
        ...(session ? [{ id: "apariencia", label: "Apariencia", icon: Palette }] : []),
        ...(session ? [{ id: "misPagos", label: "Mis pagos", icon: Receipt }] : []),
        { id: "planes", label: "Planes y precios", icon: Shield },
      ],
    },
    {
      id: "ayuda", label: "Ayuda", icon: HelpCircle,
      items: [
        { id: "ayuda", label: "Centro de ayuda", icon: HelpCircle },
        { id: "tutorial", label: "Ver el tutorial de bienvenida", icon: Sparkles, accion: "tutorial" },
        ...(perfil?.es_admin ? [{ id: "admin", label: "Admin", icon: Shield }] : []),
      ],
    },
  ];
  const navButton = (item) => {
    const Icon = item.icon;
    const active = view === item.id;
    return (
      <button key={item.id} onClick={() => setView(item.id)}
        style={{ background: active ? COLORS.surface2 : "transparent", border: `1px solid ${active ? COLORS.azulPalido : COLORS.surface2}`, color: active ? COLORS.azulPalido : COLORS.muted }}
        className="px-3 py-2 rounded-lg text-sm font-semibold flex items-center gap-2 whitespace-nowrap">
        <Icon size={15} /> <span>{item.label}</span>
      </button>
    );
  };

  return (
    <div
      style={{
        position: "relative",
        backgroundColor: COLORS.bg,
        color: COLORS.text,
        minHeight: "100vh",
        fontFamily: "'Cabin', sans-serif",
        overflowX: "hidden",
      }}
      className="w-full"
    >
      <style>{FONTS}</style>
      <BackgroundField />

      <header style={{ position: "sticky", top: 0, zIndex: 50, borderBottom: `1px solid ${COLORS.azulClaro}2e`, background: conAlpha(COLORS.bg, 0.66), backdropFilter: "blur(14px)" }}
        className="px-4 sm:px-8 py-6">
        <div className="max-w-5xl mx-auto flex items-center justify-between flex-wrap gap-4">
          <div className="flex items-center gap-2">
            <button onClick={() => setView("search")} className="flex items-center gap-2">
              {!logoError ? (
                <img
                  src={(localStorage.getItem(TEMA_MODO_KEY) || "noche") === "dia" ? "/branding/logo.png" : "/branding/logo-noche.png"}
                  alt="Encuentra Cartas" onError={() => setLogoError(true)} style={{ height: 40, width: "auto" }} />
              ) : (
                <>
                  <Sparkles size={22} color={COLORS.azulPalido} />
                  <h1 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-2xl sm:text-3xl font-bold">
                    Encuentra <span style={{ color: COLORS.azulClaro }}>Cartas</span>
                  </h1>
                </>
              )}
            </button>
            {/* Carrito + chats en celular: en vez de los botones flotantes grandes
                (que en celular chocarían con la nueva cintilla de navegación de
                abajo), una cintilla chica junto al logo -- sin taparlo, porque
                vive en el mismo grupo flex que el logo, no encimada -- que se
                despliega hacia el lado para mostrar los dos botones completos. */}
            <CintillaMovilCarritoChats carritoCount={carrito.length} mensajesNoLeidos={mensajesNoLeidos} mostrarChats={!!session} onCarrito={() => setView("carrito")} onChats={() => setView("inbox")} />
          </div>
          <nav className="relative flex flex-wrap gap-2 items-center">
            <button onClick={irAVender}
              style={{ background: `linear-gradient(90deg, ${COLORS.gold}, #FFB84D)`, color: COLORS.textoOscuro }}
              className="hidden sm:flex px-3 py-2 rounded-lg text-sm font-bold items-center gap-2 whitespace-nowrap shadow-sm hover:brightness-105">
              <Tag size={15} /> <span>Vender</span>
            </button>
            <div className="hidden sm:flex gap-2 items-center">{navEsenciales.map(navButton)}</div>

            {/* Foto de perfil: acceso directo a "Mi cuenta" (o a crear cuenta si
                no hay sesión) — separado del menú de tres líneas, que abre el resto
                (Torneos, Wishlist, Planes, Mis pagos, Ayuda, Admin, Cerrar sesión). */}
            {session ? (
              <button onClick={() => setView("miCuenta")} style={{ color: COLORS.muted }} className="p-1 rounded-lg flex items-center">
                <AvatarImg url={perfil?.avatar_url} size={32} />
              </button>
            ) : (
              <button onClick={() => setShowAccountModal(true)} title="Iniciar sesión o crear cuenta" style={{ color: COLORS.muted }} className="p-2 rounded-lg flex items-center">
                <User size={20} />
              </button>
            )}
            <button onClick={() => setShowDrawer(true)} style={{ color: COLORS.muted }} className="p-1 rounded-lg flex items-center">
              <Menu size={20} />
            </button>
          </nav>
        </div>
      </header>

      {adminStash && (
        <div style={{ position: "relative", zIndex: 10, background: COLORS.gold, color: COLORS.textoOscuro }}
          className="px-4 py-2 text-sm font-semibold flex items-center justify-center gap-3 flex-wrap text-center">
          <span>🔀 Estás usando el sub-perfil "{perfil?.nombre}"</span>
          <button onClick={volverAMiCuentaAdmin} className="underline whitespace-nowrap">Volver a mi cuenta admin</button>
        </div>
      )}

      {showDrawer && (
        <Drawer
          session={session}
          perfil={perfil}
          grupos={navGrupos}
          view={view}
          onNavigate={(id) => { setView(id); setShowDrawer(false); }}
          onEditarPerfil={() => { setView("miCuenta"); setShowDrawer(false); }}
          onVerTutorial={() => { setShowOnboarding(true); setShowDrawer(false); }}
          onLogout={() => { handleLogout(); setShowDrawer(false); }}
          onLogin={() => { setShowAccountModal(true); setShowDrawer(false); }}
          onClose={() => setShowDrawer(false)}
        />
      )}

      {showOnboarding && <OnboardingTutorial onClose={() => setShowOnboarding(false)} />}

      {showAccountModal && <AccountModal onClose={() => setShowAccountModal(false)} onAuthed={handleAuthed} />}
      {confirmarInfo && (
        <ConfirmarCorreoModal tokenHash={confirmarInfo.tokenHash} tipo={confirmarInfo.tipo}
          onConfirmado={confirmarCorreoConfirmado} onCerrar={() => setConfirmarInfo(null)} />
      )}
      {session && perfilChecked && !perfil && (
        <CompletarPerfilOAuthModal session={session} onCreado={(p) => { setPerfil(p); procesarNuevoRegistro(session); }} onCancelar={handleLogout} />
      )}
      {chatContext && session && (
        <ChatModal
          session={session}
          otherId={chatContext.otherId}
          otherNombre={chatContext.otherNombre}
          contexto={chatContext.contexto}
          otherWhatsapp={chatContext.otherWhatsapp}
          otherFacebook={chatContext.otherFacebook}
          otherAvatar={chatContext.otherAvatar}
          onClose={() => { setChatContext(null); if (session) cargarInbox(); }}
          onLeido={cargarMensajesNoLeidos}
        />
      )}
      {mostrarBuscarCarta && session && (
        <BuscarCartaModal session={session} onClose={() => setMostrarBuscarCarta(false)} onCreado={() => setBusquedasVersion((v) => v + 1)} />
      )}

      {/* Carrito: antes era un ícono discreto arriba -- ahora es un botón
          flotante grande abajo a la izquierda (no choca con el ChatModal,
          que se ancla a la derecha) con un halo que pulsa cada cierto
          tiempo para que no pase desapercibido. Exclusivo de escritorio --
          en celular vive en CintillaMovilCarritoChats, junto al logo,
          porque este espacio ahora lo ocupa la cintilla de navegación de
          abajo. */}
      <button onClick={() => setView("carrito")} aria-label="Carrito"
        style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro, boxShadow: "0 6px 20px rgba(0,0,0,0.4)" }}
        className="hidden sm:flex fixed bottom-4 left-4 sm:bottom-6 sm:left-6 z-40 w-14 h-14 rounded-full items-center justify-center">
        <span style={{ border: `2px solid ${COLORS.azulPalido}`, animation: "ringPulse 1.8s ease-out infinite" }}
          className="absolute inset-0 rounded-full pointer-events-none" aria-hidden="true" />
        <span style={{ border: `2px solid ${COLORS.azulPalido}`, animation: "ringPulse 1.8s ease-out .6s infinite" }}
          className="absolute inset-0 rounded-full pointer-events-none" aria-hidden="true" />
        <ShoppingCart size={24} />
        {carrito.length > 0 && (
          <span style={{ background: COLORS.gold, color: COLORS.textoOscuro, border: `2px solid ${COLORS.bg}` }}
            className="absolute -top-1 -right-1 rounded-full text-xs font-bold w-5 h-5 flex items-center justify-center">
            {carrito.length > 9 ? "9+" : carrito.length}
          </span>
        )}
      </button>

      {/* Chats: antes había que encontrar el ícono de Mensajes arriba --
          ahora es otro botón flotante junto al carrito (mismo halo que
          pulsa), de un color distinto para no confundirse con el carrito,
          con la bolita de mensajes sin leer en el color de acento del tema
          actual (cambia solo si se personaliza en Apariencia). Exclusivo
          de escritorio, mismo motivo que el carrito de arriba. */}
      {session && (
        <button onClick={() => setView("inbox")} aria-label="Mensajes"
          style={{ background: COLORS.violeta, color: "#fff", boxShadow: "0 6px 20px rgba(0,0,0,0.4)" }}
          className="hidden sm:flex fixed bottom-4 left-20 sm:bottom-6 sm:left-24 z-40 w-14 h-14 rounded-full items-center justify-center">
          <span style={{ border: `2px solid ${COLORS.violeta}`, animation: "ringPulse 1.8s ease-out infinite" }}
            className="absolute inset-0 rounded-full pointer-events-none" aria-hidden="true" />
          <span style={{ border: `2px solid ${COLORS.violeta}`, animation: "ringPulse 1.8s ease-out .6s infinite" }}
            className="absolute inset-0 rounded-full pointer-events-none" aria-hidden="true" />
          <MessageCircle size={24} />
          {mensajesNoLeidos > 0 && (
            <span style={{ background: COLORS.azulPalido, color: COLORS.textoOscuro, border: `2px solid ${COLORS.bg}` }}
              className="absolute -top-1 -right-1 rounded-full text-xs font-bold w-5 h-5 flex items-center justify-center">
              {mensajesNoLeidos > 9 ? "9+" : mensajesNoLeidos}
            </span>
          )}
        </button>
      )}

      <NotificationBell session={session} onNavigate={setView} />

      <CintillaMovilAbajo view={view} setView={setView} irAVender={irAVender} />

      {/* pb-24 en celular: deja espacio para que la cintilla de navegación
          fija de abajo (CintillaMovilAbajo) no tape lo último del contenido. */}
      <main style={{ position: "relative", zIndex: 1 }} className="max-w-5xl mx-auto px-4 sm:px-8 pt-10 pb-28 sm:py-10">
        {/* SEARCH */}
        {view === "search" && (
          <div>
            {!query.trim() && (() => {
              const banners = (
                <>
                  <SorteoDestacadoBanner onAbrirSorteo={abrirSorteo} />
                  <PlanesPromoBanner perfil={perfil} onVerPlanes={() => setView("planes")} />
                  <button onClick={() => (session ? setMostrarBuscarCarta(true) : setShowAccountModal(true))}
                    style={{ background: `${COLORS.violeta}1a`, border: `1px solid ${COLORS.violeta}55` }}
                    className="w-full rounded-xl p-3 mb-3 flex items-center gap-3 text-left hover:brightness-110 transition">
                    <Search size={20} color={COLORS.violeta} className="shrink-0" />
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-semibold">🔍 ¿Buscas alguna carta?</p>
                      <p style={{ color: COLORS.muted }} className="text-xs truncate">Publícala y que alguien que la tenga te contacte directo</p>
                    </div>
                    <span style={{ color: COLORS.violeta }} className="text-xs font-semibold whitespace-nowrap">Publicar →</span>
                  </button>
                  <BusquedasCarrusel key={busquedasVersion} onAbrir={() => setView("busquedas")} />
                </>
              );
              return esVisitanteNuevo ? <NovedadesCondensadas>{banners}</NovedadesCondensadas> : banners;
            })()}
            <div className="text-center mb-10" style={{ animation: "fadeUp .5s ease both" }}>
              <div style={{ background: `${COLORS.violeta}1f`, border: `1px solid ${COLORS.violeta}59`, color: "#C9B6FF" }}
                className="inline-flex items-center gap-2 px-3.5 py-1.5 rounded-full text-xs font-semibold tracking-wide mb-5">
                <span style={{ width: 6, height: 6, borderRadius: "50%", background: COLORS.violeta, boxShadow: `0 0 8px ${COLORS.violeta}`, animation: "pulseGlow 1.6s ease-in-out infinite" }} />
                NUEVO · Rangos rediseñados
              </div>
              <h1 style={{ fontFamily: "'Baloo 2', sans-serif", fontSize: "clamp(28px,5vw,44px)", letterSpacing: "-0.5px", lineHeight: 1.08 }} className="font-bold mb-3">
                Encuentra la carta<br />
                <span style={{ background: `linear-gradient(90deg, ${COLORS.azulPalido}, ${COLORS.azulClaro}, ${COLORS.violeta})`, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" }}>
                  que estás cazando
                </span>
              </h1>
              <p style={{ color: COLORS.muted }} className="text-sm sm:text-base max-w-md mx-auto mb-7">
                Busca entre cartas publicadas por tiendas y coleccionistas cerca de ti.
              </p>
              <div style={{ background: `${COLORS.surface2}d9`, border: `1px solid ${COLORS.azulClaro}59` }}
                className="max-w-xl mx-auto rounded-2xl p-2 flex items-center gap-2">
                <Search size={20} color={COLORS.azulMedio} className="ml-2 shrink-0" />
                <input value={query} onChange={(e) => setQuery(e.target.value)}
                  placeholder="Busca una carta..." style={{ color: COLORS.text }}
                  className="bg-transparent outline-none w-full py-2 text-lg" />
              </div>

              <div className="flex flex-wrap items-center justify-center gap-1.5 mt-4">
                <p style={{ color: COLORS.muted }} className="text-xs mr-1">¿Qué TCG te interesa?</p>
                {[{ key: "todos", label: "Todos" }, ...TCG_OPCIONES].map((o) => (
                  <button key={o.key} type="button" onClick={() => setTcgFiltro(o.key)}
                    style={{
                      background: tcgFiltro === o.key ? COLORS.surface2 : "transparent",
                      border: `1px solid ${tcgFiltro === o.key ? COLORS.azulClaro : COLORS.surface2}`,
                      color: tcgFiltro === o.key ? COLORS.azulClaro : COLORS.muted,
                    }}
                    className="px-3 py-1 rounded-full text-xs font-semibold">
                    {o.label}
                  </button>
                ))}
              </div>

              <button type="button" onClick={irAVender}
                style={{ background: `linear-gradient(90deg, ${COLORS.gold}, #FFB84D)`, color: COLORS.textoOscuro }}
                className="w-full max-w-xl mx-auto mt-5 rounded-2xl px-6 py-4 flex items-center justify-center gap-2 font-bold text-base sm:text-lg shadow-lg hover:brightness-105 active:scale-[0.99] transition">
                <Tag size={22} />
                Vende tus cartas
              </button>
            </div>

            {esVisitanteNuevo && !query.trim() && <ComoFuncionaGuia />}

            {searching && <Loading label="Buscando en tiendas y mercado..." />}
            {searchError && <ErrorBox message={searchError} />}

            {!searching && !query.trim() && (
              <div>
                <p className="text-center text-sm mb-10" style={{ color: COLORS.muted }}>
                  Escribe el nombre de una carta para buscar, o explora lo más reciente aquí abajo.
                </p>

                {news.length > 0 && (
                  <div className="mb-10">
                    <div className="flex items-center justify-between mb-3">
                      <h3 style={{ color: COLORS.azulClaro }} className="font-semibold text-sm uppercase">📢 Anuncios recientes</h3>
                      <button onClick={() => setView("news")} style={{ color: COLORS.azulPalido }} className="text-xs font-semibold">Ver todos</button>
                    </div>
                    <div className="flex gap-3 overflow-x-auto pb-2">
                      {news.slice(0, 5).map((n) => (
                        <button key={n.id} onClick={() => setView("news")}
                          style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}`, minWidth: 220, maxWidth: 220 }}
                          className="text-left rounded-xl overflow-hidden shrink-0">
                          {imagenesDeAnuncio(n).length > 0 ? (
                            <MiniaturaAnuncio n={n} style={{ height: 100, objectFit: "cover" }} className="w-full" />
                          ) : (
                            <div style={{ background: COLORS.surface2, height: 100 }} className="flex items-center justify-center">
                              <Megaphone size={24} color={COLORS.muted} />
                            </div>
                          )}
                          <div className="p-3">
                            <p className="text-sm font-semibold line-clamp-1">{n.titulo}</p>
                            <p style={{ color: COLORS.muted }} className="text-xs line-clamp-2 mt-1">{n.contenido}</p>
                          </div>
                        </button>
                      ))}
                    </div>
                  </div>
                )}

                <h3 style={{ color: COLORS.azulClaro }} className="font-semibold text-sm uppercase mb-3">🛒 Mercado</h3>
                <TiendasAuroraCarrusel onAbrirTienda={openStore} />
                <div className="flex gap-2 flex-wrap mb-3 items-center">
                  {[{ id: "todos", label: "Todo" }, { id: "carta", label: "Cartas" }, { id: "sellado", label: "Sellado" }, { id: "accesorio", label: "Accesorios" }].map((t) => (
                    <button key={t.id} onClick={() => setTipoMercadoTab(t.id)}
                      style={{ background: tipoMercadoTab === t.id ? `${COLORS.azul}55` : COLORS.surface2, border: `1px solid ${tipoMercadoTab === t.id ? COLORS.azulPalido : COLORS.surface2}`, color: tipoMercadoTab === t.id ? COLORS.azulPalido : COLORS.muted }}
                      className="rounded-lg px-3 py-1.5 text-xs font-semibold">
                      {t.label}
                    </button>
                  ))}
                  <button onClick={() => setFiltrosAbiertos((v) => !v)}
                    style={{ background: filtrosActivos ? `${COLORS.gold}22` : "transparent", border: `1px solid ${filtrosActivos ? COLORS.gold : COLORS.surface2}`, color: filtrosActivos ? COLORS.gold : COLORS.muted }}
                    className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1">
                    🔎 Filtros{filtrosActivos ? ` (${Object.values(filtros).filter(Boolean).length})` : ""}
                  </button>
                </div>
                {filtrosAbiertos && (
                  <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-4 mb-6 grid sm:grid-cols-5 gap-2">
                    <input placeholder="Precio mín." type="number" value={filtros.precioMin}
                      onChange={(e) => setFiltros((f) => ({ ...f, precioMin: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm" />
                    <input placeholder="Precio máx." type="number" value={filtros.precioMax}
                      onChange={(e) => setFiltros((f) => ({ ...f, precioMax: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm" />
                    <select value={filtros.idioma} onChange={(e) => setFiltros((f) => ({ ...f, idioma: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Idioma (cualquiera)</option>
                      {IDIOMA_OPCIONES.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}
                    </select>
                    <select value={filtros.condicion} onChange={(e) => setFiltros((f) => ({ ...f, condicion: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Estado (cualquiera)</option>
                      {CONDICION_OPCIONES.map((o) => <option key={o.key} value={o.key}>{o.key} · {o.label}</option>)}
                    </select>
                    <ZonaSelector incluirTodas value={filtros.zona}
                      onChange={(v) => setFiltros((f) => ({ ...f, zona: v }))} />
                    <select value={ordenResultados} onChange={(e) => setOrdenResultados(e.target.value)}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Ordenar por: relevancia</option>
                      <option value="precio_asc">Precio: menor a mayor</option>
                      <option value="precio_desc">Precio: mayor a menor</option>
                    </select>
                    {filtrosActivos && (
                      <button onClick={() => setFiltros({ precioMin: "", precioMax: "", idioma: "", condicion: "", zona: "" })}
                        style={{ color: COLORS.muted }} className="text-xs text-left sm:col-span-5">Limpiar filtros</button>
                    )}
                  </div>
                )}
                {(() => {
                  const loadingMercado = loadingMarket || loadingMarketTiendas;
                  const mercadoCompleto = marketNormalizado(market, marketTiendas);
                  const mercadoVisible = ordenarPorPrecio(mercadoCompleto.filter(pasaFiltroTcg).filter((r) => tipoMercadoTab === "todos" || r.tipo === tipoMercadoTab).filter(pasaFiltros));
                  return (
                    <>
                      {loadingMercado && <SkeletonGrid />}
                      {!loadingMercado && mercadoVisible.length === 0 && (
                        <p style={{ color: COLORS.muted }} className="text-sm text-center py-16">
                          {mercadoCompleto.length === 0
                            ? "Todavía no hay publicaciones en el mercado. En cuanto alguien se registre como cuenta individual (o una tienda) publique una carta, aparecerá aquí automáticamente."
                            : filtrosActivos
                              ? "Nadie tiene algo así con esos filtros. Prueba quitando alguno."
                              : "Nadie ha publicado nada así todavía en el Mercado."}
                        </p>
                      )}
                      <div className="columns-2 sm:columns-3 lg:columns-4 gap-4">
                        {mercadoVisible.map((r) => (
                    <div key={`${r._esTienda ? "t" : "m"}-${r.id}`} onClick={() => abrirDetalle(r.id, r._tabla)} style={{ background: `${COLORS.surface2}99`, border: `1px solid ${estaDestacado(r) ? COLORS.azulPalido + "66" : COLORS.azulClaro + "29"}`, cursor: "pointer" }} className="rounded-2xl overflow-hidden flex flex-col mb-4 break-inside-avoid transition-transform duration-200 hover:-translate-y-1 hover:shadow-[0_12px_28px_rgba(0,0,0,0.35)]">
                      <div style={{ background: COLORS.surface2 }} className="aspect-[4/5] flex items-center justify-center p-3">
                        {miniaturaListing(r) ? (
                          <img src={miniaturaListing(r)} alt={r.carta} style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
                        ) : (
                          <Package size={40} color={COLORS.muted} />
                        )}
                      </div>
                      <div className="p-3 flex flex-col flex-1 gap-1">
                        <div className="flex items-center gap-1 flex-wrap">
                          <Badge color={r._esTienda ? COLORS.azulPalido : COLORS.azulClaro}>{r._esTienda ? "Tienda" : "Mercado"}</Badge>
                          {r.tipo === "sellado" && <Badge color={COLORS.azulMedio}>Sellado</Badge>}
                          {r.tipo === "accesorio" && <Badge color={COLORS.gold}>Accesorio</Badge>}
                          {r.tipo === "carta" && <IdiomaBadge idioma={r.idioma} />}
                          {r.tipo === "carta" && <EstadoCartaBadge condicion={r.condicion} />}
                          {r.tipo === "carta" && <GradeoBadge gradeada={r.gradeada} grado_empresa={r.grado_empresa} grado_empresa_otro={r.grado_empresa_otro} grado_calificacion={r.grado_calificacion} />}
                          {!r._esTienda && <BuzonBadge tienda={r.buzon_tienda} />}
                          <PlanBadge perfil={r.perfiles} />
                          <BoostBadge item={r} />
                        </div>
                        <p className="font-semibold text-sm leading-snug line-clamp-2">{r.carta}</p>
                        {r.tipo === "accesorio" ? (
                          <p style={{ color: COLORS.muted }} className="text-xs truncate">{r.descripcion || r.zona}</p>
                        ) : (
                          <p style={{ color: COLORS.muted }} className="text-xs truncate">{r.set_nombre}{r.set_nombre && zonaDe(r) ? " · " : ""}{zonaDe(r)}</p>
                        )}
                        <div className="mt-1">
                          <PrecioConOferta precio={r.precio} precioAntes={r.precio_antes} size="md" />
                        </div>
                        {r.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs -mt-1">ref. {r.precio_ref_fuente || "mercado"}: ~${Number(r.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                        {r._esTienda ? (
                          <div className="flex items-center gap-2 mt-auto pt-2">
                            <AvatarImg url={r._vendedorAvatar} size={20} />
                            <p style={{ color: COLORS.muted }} className="text-xs truncate">{r._vendedorNombre}</p>
                          </div>
                        ) : (
                          <button onClick={(e) => { e.stopPropagation(); verPerfil(r._vendedorId); }} className="flex items-center gap-2 mt-auto pt-2 hover:brightness-125">
                            <AvatarImg url={r._vendedorAvatar} size={20} />
                            <p style={{ color: COLORS.muted }} className="text-xs truncate">{r._vendedorNombre}</p>
                          </button>
                        )}
                        <div className="flex gap-1 mt-2">
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirChat(r._vendedorId, r._vendedorNombre, `${r.carta} (${r.set_nombre})${r._esTienda ? ` en ${r._vendedorNombre}` : ""}`, r._vendedorWhatsapp, r._vendedorFacebook, r._vendedorAvatar); }}
                            disabled={!r._vendedorId}
                            style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55`, opacity: r._vendedorId ? 1 : 0.4 }}
                            className="text-xs px-3 py-1.5 rounded-lg flex items-center justify-center gap-1 flex-1"
                          >
                            <MessageCircle size={12} /> Contactar
                          </button>
                          <button
                            onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: r._tabla, id: r.id, nombre: r.carta, precio: r.precio, imagen_url: miniaturaListing(r), contexto: `${r.carta} (${r.set_nombre})`, vendedorId: r._vendedorId, vendedorNombre: r._vendedorNombre, vendedorAvatar: r._vendedorAvatar, vendedorWhatsapp: r._vendedorWhatsapp, vendedorFacebook: r._vendedorFacebook }); }}
                            disabled={!r._vendedorId || r._vendedorId === session?.user?.id || enElCarrito(r._tabla, r.id)}
                            style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: (!r._vendedorId || r._vendedorId === session?.user?.id) ? 0.3 : 1 }}
                            className="text-xs px-2 py-1.5 rounded-lg flex items-center justify-center">
                            {enElCarrito(r._tabla, r.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                          </button>
                        </div>
                      </div>
                    </div>
                        ))}
                      </div>
                    </>
                  );
                })()}
              </div>
            )}

            {!searching && query.trim() && (
              <div className="max-w-3xl mx-auto mb-4">
                <div className="flex justify-center">
                  <button onClick={() => setFiltrosAbiertos((v) => !v)}
                    style={{ background: filtrosActivos ? `${COLORS.gold}22` : "transparent", border: `1px solid ${filtrosActivos ? COLORS.gold : COLORS.surface2}`, color: filtrosActivos ? COLORS.gold : COLORS.muted }}
                    className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1">
                    🔎 Filtros{filtrosActivos ? ` (${Object.values(filtros).filter(Boolean).length})` : ""}
                  </button>
                </div>
                {filtrosAbiertos && (
                  <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-4 mt-3 grid sm:grid-cols-5 gap-2">
                    <input placeholder="Precio mín." type="number" value={filtros.precioMin}
                      onChange={(e) => setFiltros((f) => ({ ...f, precioMin: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm" />
                    <input placeholder="Precio máx." type="number" value={filtros.precioMax}
                      onChange={(e) => setFiltros((f) => ({ ...f, precioMax: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm" />
                    <select value={filtros.idioma} onChange={(e) => setFiltros((f) => ({ ...f, idioma: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Idioma (cualquiera)</option>
                      {IDIOMA_OPCIONES.map((o) => <option key={o.key} value={o.key}>{o.label}</option>)}
                    </select>
                    <select value={filtros.condicion} onChange={(e) => setFiltros((f) => ({ ...f, condicion: e.target.value }))}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Estado (cualquiera)</option>
                      {CONDICION_OPCIONES.map((o) => <option key={o.key} value={o.key}>{o.key} · {o.label}</option>)}
                    </select>
                    <ZonaSelector incluirTodas value={filtros.zona}
                      onChange={(v) => setFiltros((f) => ({ ...f, zona: v }))} />
                    <select value={ordenResultados} onChange={(e) => setOrdenResultados(e.target.value)}
                      style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                      <option value="">Ordenar por: relevancia</option>
                      <option value="precio_asc">Precio: menor a mayor</option>
                      <option value="precio_desc">Precio: mayor a menor</option>
                    </select>
                    {filtrosActivos && (
                      <button onClick={() => setFiltros({ precioMin: "", precioMax: "", idioma: "", condicion: "", zona: "" })}
                        style={{ color: COLORS.muted }} className="text-xs text-left sm:col-span-5">Limpiar filtros</button>
                    )}
                  </div>
                )}
              </div>
            )}

            {(() => {
              const selladoVisible = ordenarPorPrecio(searchResults.sellado.filter(pasaFiltroTcg).filter(pasaFiltros));
              const tiendasVisibles = ordenarPorPrecio(searchResults.tiendas.filter(pasaFiltroTcg).filter(pasaFiltros));
              const mercadoVisible = ordenarPorPrecio(searchResults.mercado.filter(pasaFiltroTcg).filter(pasaFiltros));
              return (
                <>
                  {!searching && query.trim() && tiendasVisibles.length === 0 && mercadoVisible.length === 0 && selladoVisible.length === 0 && (
                    <p style={{ color: COLORS.muted }} className="text-center py-16 text-sm">
                      {filtrosActivos && (searchResults.tiendas.length + searchResults.mercado.length + searchResults.sellado.length) > 0
                        ? "Nadie tiene algo así con esos filtros. Prueba quitando alguno."
                        : `Nadie tiene "${query}" registrado todavía${tcgFiltro !== "todos" ? ` en ${TCG_LABEL[tcgFiltro] || tcgFiltro}` : ""}.`}
                    </p>
                  )}

                  <div className="grid gap-4">
                    {tiendasVisibles.map((r) => (
                <div key={r.id} onClick={() => abrirDetalle(r.id, "inventario_tienda")} style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${COLORS.azulClaro}29`, cursor: "pointer" }}
                  className="rounded-2xl p-4 flex items-center justify-between gap-4 flex-wrap transition-transform duration-200 hover:translate-x-1">
                  <div className="flex items-center gap-3">
                    {miniaturaListing(r) && <img src={miniaturaListing(r)} alt={r.carta} style={{ width: 72, height: 100, objectFit: "contain" }} />}
                    <div>
                      <div className="flex gap-2 items-center mb-1 flex-wrap"><Badge color={COLORS.azulPalido}>Tienda</Badge><p className="font-semibold text-lg">{r.carta}</p><IdiomaBadge idioma={r.idioma} /><EstadoCartaBadge condicion={r.condicion} /><GradeoBadge gradeada={r.gradeada} grado_empresa={r.grado_empresa} grado_empresa_otro={r.grado_empresa_otro} grado_calificacion={r.grado_calificacion} /><PlanBadge perfil={r.tiendas?.perfiles} /><BoostBadge item={r} /></div>
                      <p style={{ color: COLORS.muted }} className="text-sm">{r.set_nombre}</p>
                      <div className="flex items-center gap-2 mt-1">
                        <AvatarImg url={r.tiendas?.perfiles?.avatar_url} size={20} />
                        <p style={{ color: COLORS.muted }} className="text-xs">{r.tiendas?.nombre} · {r.tiendas?.zona}</p>
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <PrecioConOferta precio={r.precio} precioAntes={r.precio_antes} />
                    {r.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs">ref. {r.precio_ref_fuente || "mercado"}: ~${Number(r.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                    <div className="flex gap-1 mt-2 justify-end">
                      <button
                        onClick={(e) => { e.stopPropagation(); abrirChat(r.tiendas?.perfil_id, r.tiendas?.nombre, `${r.carta} (${r.set_nombre}) en ${r.tiendas?.nombre}`, null, null, r.tiendas?.perfiles?.avatar_url); }}
                        disabled={!r.tiendas?.perfil_id}
                        style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55`, opacity: r.tiendas?.perfil_id ? 1 : 0.4 }}
                        className="text-xs px-3 py-1.5 rounded-lg flex items-center gap-1">
                        <MessageCircle size={12} /> Contactar
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: "inventario_tienda", id: r.id, nombre: r.carta, precio: r.precio, imagen_url: miniaturaListing(r), contexto: `${r.carta} (${r.set_nombre}) en ${r.tiendas?.nombre}`, vendedorId: r.tiendas?.perfil_id, vendedorNombre: r.tiendas?.nombre, vendedorAvatar: r.tiendas?.perfiles?.avatar_url }); }}
                        disabled={!r.tiendas?.perfil_id || enElCarrito("inventario_tienda", r.id)}
                        style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: r.tiendas?.perfil_id ? 1 : 0.3 }}
                        className="text-xs px-2 py-1.5 rounded-lg flex items-center">
                        {enElCarrito("inventario_tienda", r.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
              {mercadoVisible.map((r) => (
                <div key={r.id} onClick={() => abrirDetalle(r.id, "mercado_listings")} style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${COLORS.azulClaro}29`, cursor: "pointer" }}
                  className="rounded-2xl p-4 flex items-center justify-between gap-4 flex-wrap transition-transform duration-200 hover:translate-x-1">
                  <div className="flex items-center gap-3">
                    {miniaturaListing(r) && <img src={miniaturaListing(r)} alt={r.carta} style={{ width: 72, height: 100, objectFit: "contain" }} />}
                    <div>
                      <div className="flex gap-2 items-center mb-1 flex-wrap"><Badge color={COLORS.azulClaro}>Vendedor individual</Badge>{r.tipo === "sellado" && <Badge color={COLORS.azulMedio}>Sellado</Badge>}{r.tipo === "accesorio" && <Badge color={COLORS.gold}>Accesorio</Badge>}<p className="font-semibold text-lg">{r.carta}</p>{r.tipo === "carta" && <IdiomaBadge idioma={r.idioma} />}{r.tipo === "carta" && <EstadoCartaBadge condicion={r.condicion} />}{r.tipo === "carta" && <GradeoBadge gradeada={r.gradeada} grado_empresa={r.grado_empresa} grado_empresa_otro={r.grado_empresa_otro} grado_calificacion={r.grado_calificacion} />}<BuzonBadge tienda={r.buzon_tienda} /><PlanBadge perfil={r.perfiles} /><BoostBadge item={r} /></div>
                      {r.tipo === "accesorio" ? (
                        <p style={{ color: COLORS.muted }} className="text-sm line-clamp-2">{r.descripcion}</p>
                      ) : (
                        <p style={{ color: COLORS.muted }} className="text-sm">{r.set_nombre}</p>
                      )}
                      <p style={{ color: COLORS.muted }} className="text-xs mt-1">{r.zona}</p>
                      <button onClick={(e) => { e.stopPropagation(); verPerfil(r.perfil_id); }} className="flex items-center gap-2 mt-2 hover:brightness-125">
                        <AvatarImg url={r.perfiles?.avatar_url} size={22} />
                        <p style={{ color: COLORS.muted }} className="text-xs">{r.perfiles?.nombre || "Usuario"}</p>
                      </button>
                    </div>
                  </div>
                  <div className="text-right">
                    <PrecioConOferta precio={r.precio} precioAntes={r.precio_antes} />
                    {r.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs">ref. {r.precio_ref_fuente || "mercado"}: ~${Number(r.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                    <div className="flex gap-1 mt-2 justify-end">
                      <button
                        onClick={(e) => { e.stopPropagation(); abrirChat(r.perfil_id, r.perfiles?.nombre, `${r.carta} (${r.set_nombre})`, r.perfiles?.whatsapp, r.perfiles?.facebook, r.perfiles?.avatar_url); }}
                        style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55` }}
                        className="text-xs px-3 py-1.5 rounded-lg flex items-center gap-1">
                        <MessageCircle size={12} /> Contactar
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: "mercado_listings", id: r.id, nombre: r.carta, precio: r.precio, imagen_url: miniaturaListing(r), contexto: `${r.carta} (${r.set_nombre})`, vendedorId: r.perfil_id, vendedorNombre: r.perfiles?.nombre, vendedorAvatar: r.perfiles?.avatar_url, vendedorWhatsapp: r.perfiles?.whatsapp, vendedorFacebook: r.perfiles?.facebook }); }}
                        disabled={!r.perfil_id || r.perfil_id === session?.user?.id || enElCarrito("mercado_listings", r.id)}
                        style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: (!r.perfil_id || r.perfil_id === session?.user?.id) ? 0.3 : 1 }}
                        className="text-xs px-2 py-1.5 rounded-lg flex items-center">
                        {enElCarrito("mercado_listings", r.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
              {selladoVisible.map((r) => (
                <div key={`sel-${r.id}`} onClick={() => abrirDetalle(r.id, "sellado_tienda")} style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${COLORS.azulClaro}29`, cursor: "pointer" }}
                  className="rounded-2xl p-4 flex items-center justify-between gap-4 flex-wrap transition-transform duration-200 hover:translate-x-1">
                  <div className="flex items-center gap-3">
                    {r.imagen_url && <img src={r.imagen_url} alt={r.producto} style={{ width: 72, height: 100, objectFit: "contain" }} />}
                    <div>
                      <div className="flex gap-2 items-center mb-1 flex-wrap"><Badge color={COLORS.azulPalido}>Tienda</Badge><Badge color={COLORS.azulMedio}>Sellado</Badge><p className="font-semibold text-lg">{r.producto}</p><PlanBadge perfil={r.tiendas?.perfiles} /><BoostBadge item={r} /></div>
                      <div className="flex items-center gap-2 mt-1">
                        <AvatarImg url={r.tiendas?.perfiles?.avatar_url} size={20} />
                        <p style={{ color: COLORS.muted }} className="text-xs">{r.tiendas?.nombre} · {r.tiendas?.zona}</p>
                      </div>
                    </div>
                  </div>
                  <div className="text-right">
                    <PrecioConOferta precio={r.precio} precioAntes={r.precio_antes} />
                    {r.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs">ref. {r.precio_ref_fuente || "mercado"}: ~${Number(r.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                    <div className="flex gap-1 mt-2 justify-end">
                      <button
                        onClick={(e) => { e.stopPropagation(); abrirChat(r.tiendas?.perfil_id, r.tiendas?.nombre, `${r.producto} en ${r.tiendas?.nombre}`, null, null, r.tiendas?.perfiles?.avatar_url); }}
                        disabled={!r.tiendas?.perfil_id}
                        style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55`, opacity: r.tiendas?.perfil_id ? 1 : 0.4 }}
                        className="text-xs px-3 py-1.5 rounded-lg flex items-center gap-1">
                        <MessageCircle size={12} /> Contactar
                      </button>
                      <button
                        onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: "sellado_tienda", id: r.id, nombre: r.producto, precio: r.precio, imagen_url: r.imagen_url, contexto: `${r.producto} en ${r.tiendas?.nombre}`, vendedorId: r.tiendas?.perfil_id, vendedorNombre: r.tiendas?.nombre, vendedorAvatar: r.tiendas?.perfiles?.avatar_url }); }}
                        disabled={!r.tiendas?.perfil_id || enElCarrito("sellado_tienda", r.id)}
                        style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: r.tiendas?.perfil_id ? 1 : 0.3 }}
                        className="text-xs px-2 py-1.5 rounded-lg flex items-center">
                        {enElCarrito("sellado_tienda", r.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                      </button>
                    </div>
                  </div>
                </div>
              ))}
                  </div>
                </>
              );
            })()}
          </div>
        )}

        {/* DIRECTORY */}
        {view === "directory" && (
          <div>
            <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-xl font-bold mb-3">Directorio de tiendas</h2>
            <div className="flex flex-wrap items-center gap-1.5 mb-6">
              <p style={{ color: COLORS.muted }} className="text-xs mr-1">TCG:</p>
              {[{ key: "todos", label: "Todos" }, ...TCG_OPCIONES].map((o) => (
                <button key={o.key} type="button" onClick={() => setTcgFiltro(o.key)}
                  style={{
                    background: tcgFiltro === o.key ? COLORS.surface2 : "transparent",
                    border: `1px solid ${tcgFiltro === o.key ? COLORS.azulClaro : COLORS.surface2}`,
                    color: tcgFiltro === o.key ? COLORS.azulClaro : COLORS.muted,
                  }}
                  className="px-3 py-1 rounded-full text-xs font-semibold">
                  {o.label}
                </button>
              ))}
            </div>
            {loadingTiendas && <Loading label="Cargando tiendas desde Supabase..." />}
            {errorTiendas && <ErrorBox message={errorTiendas} />}

            {!planDe(perfil).ubicacion ? (
              <div className="mb-6">
                <UpsellCard requiere={PLAN_INFO.superball} plan="superball" onIrAPlanes={() => setView("planes")}>
                  Filtra tiendas por zona y encuentra la más cercana con tu ubicación.
                </UpsellCard>
              </div>
            ) : (
              <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-4 mb-4 flex flex-wrap items-center gap-3">
                <select value={filtroZona} onChange={(e) => setFiltroZona(e.target.value)}
                  style={{ background: COLORS.bg, color: COLORS.text, border: `1px solid ${COLORS.surface2}` }} className="rounded-lg px-2 py-2 text-sm">
                  <option value="">Todas las zonas</option>
                  {zonasDisponibles.map((z) => <option key={z} value={z}>{z}</option>)}
                </select>
                <button onClick={usarMiUbicacion} disabled={buscandoUbicacion}
                  style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55` }}
                  className="rounded-lg px-3 py-2 text-xs font-semibold flex items-center gap-1">
                  <Navigation size={14} /> {buscandoUbicacion ? "Buscando tu ubicación..." : ubicacionUsuario ? "📍 Ubicación activa" : "Usar mi ubicación"}
                </button>
                {ubicacionUsuario && (
                  <button onClick={() => setUbicacionUsuario(null)} style={{ color: COLORS.muted }} className="text-xs underline">Quitar</button>
                )}
                {errorUbicacion && <p style={{ color: "#C24444" }} className="text-xs">{errorUbicacion}</p>}
              </div>
            )}

            {tiendaMasCercana && (
              <div style={{ background: `${COLORS.gold}15`, border: `1px solid ${COLORS.gold}55` }} className="rounded-xl p-4 mb-6 text-sm">
                📍 Tu tienda más cercana es <strong>{tiendaMasCercana.nombre}</strong>, a {formatoDistancia(tiendaMasCercana._distanciaKm)}.
              </div>
            )}

            {!loadingTiendas && tiendasFiltradas.length === 0 && (
              <p style={{ color: COLORS.muted }} className="text-sm text-center py-16">No hay tiendas en esa zona todavía.</p>
            )}

            <div className="grid sm:grid-cols-2 gap-4">
              {tiendasFiltradas.map((store, i) => (
                <div key={store.id} onClick={() => openStore(store)}
                  style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${planDe(store.perfiles).color}44` }}
                  className="text-left rounded-2xl p-5 cursor-pointer transition-transform duration-200 hover:-translate-y-1 hover:shadow-[0_10px_24px_rgba(0,0,0,0.3)]">
                  <div className="flex items-start justify-between gap-2 flex-wrap">
                    <button onClick={(e) => { e.stopPropagation(); verPerfil(store.perfil_id); }} className="flex items-center gap-2 flex-wrap hover:underline">
                      <AvatarImg url={store.perfiles?.avatar_url} size={28} />
                      <p className="font-semibold text-lg">{store.nombre}</p>
                      <PlanBadge perfil={store.perfiles} />
                      <VerificadoBadge perfil={store.perfiles} />
                      <TiendaVerificadaBadge tienda={store} />
                    </button>
                    <div className="flex items-center gap-1 flex-wrap">
                      {store._distanciaKm != null && <Badge color={COLORS.gold}>📍 {formatoDistancia(store._distanciaKm)}</Badge>}
                      {store.zona && <Badge color={colorFor(i)}>{store.zona}</Badge>}
                    </div>
                  </div>
                  <p style={{ color: COLORS.muted }} className="text-sm mt-2 flex items-start gap-1">
                    {store.sin_local ? (
                      <><Store size={14} className="mt-0.5 shrink-0" /> Sin local físico — venta en línea</>
                    ) : (
                      <><MapPin size={14} className="mt-0.5 shrink-0" /> {store.direccion}</>
                    )}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* CARRITO */}
        {view === "carrito" && (
          <CarritoView
            carrito={carrito}
            onQuitar={quitarDelCarrito}
            onRequireLogin={() => setShowAccountModal(true)}
            onEnviado={() => setCarrito([])}
            session={session}
          />
        )}

        {/* NEWS */}
        {view === "news" && (
          <div>
            <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-xl font-bold mb-6">Anuncios y noticias</h2>
            {loadingNews && <Loading label="Cargando..." />}
            {!loadingNews && news.length === 0 && (
              <p style={{ color: COLORS.muted }} className="text-sm text-center py-16">
                Todavía no hay anuncios publicados.
              </p>
            )}
            <div className="grid gap-4">
              {news.map((n) => (
                <div key={n.id} style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-xl p-5 min-w-0">
                  <div className="flex items-center justify-between gap-2 flex-wrap mb-2">
                    <div className="flex items-center gap-2">
                      <AvatarImg url={n.tiendas?.perfiles?.avatar_url} size={24} />
                      <p style={{ color: COLORS.muted }} className="text-xs font-semibold">{n.tiendas?.nombre || "Encuentra Cartas"}</p>
                    </div>
                    <Badge color={n.tipo === "anuncio" ? COLORS.azulPalido : COLORS.azulMedio}>{n.tipo}</Badge>
                  </div>
                  <GaleriaAnuncio n={n} maxHeight={260} imgClassName="rounded-lg mb-3 w-full" />
                  <p className="font-semibold text-lg">{n.titulo}</p>
                  <p style={{ color: COLORS.muted }} className="text-sm mt-1">{n.contenido}</p>
                  <p style={{ color: COLORS.muted }} className="text-xs mt-2">
                    {new Date(n.fecha_publicacion || n.created_at).toLocaleDateString("es-MX", { day: "numeric", month: "short", year: "numeric" })}
                  </p>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* MENSAJES */}
        {view === "inbox" && session && (
          <div>
            <div className="flex items-center justify-between gap-2 flex-wrap mb-6">
              <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-xl font-bold">Mensajes</h2>
              <div className="flex gap-2">
                <button onClick={() => setTabInbox("mensajes")}
                  style={{ background: tabInbox === "mensajes" ? COLORS.surface2 : "transparent", border: `1px solid ${tabInbox === "mensajes" ? COLORS.azulPalido : COLORS.surface2}`, color: tabInbox === "mensajes" ? COLORS.azulPalido : COLORS.muted }}
                  className="px-3 py-1.5 rounded-lg text-sm font-semibold">Mensajes</button>
                <button onClick={() => setTabInbox("papelera")}
                  style={{ background: tabInbox === "papelera" ? COLORS.surface2 : "transparent", border: `1px solid ${tabInbox === "papelera" ? COLORS.azulPalido : COLORS.surface2}`, color: tabInbox === "papelera" ? COLORS.azulPalido : COLORS.muted }}
                  className="px-3 py-1.5 rounded-lg text-sm font-semibold flex items-center gap-1"><Trash2 size={14} /> Papelera{papelera.length > 0 ? ` (${papelera.length})` : ""}</button>
              </div>
            </div>

            {!pushChatOk && (
              <div style={{ background: `${COLORS.azulMedio}11`, border: `1px solid ${COLORS.azulMedio}55` }} className="rounded-xl p-4 mb-6 flex items-center justify-between gap-4 flex-wrap">
                <p className="text-sm">Activa las notificaciones push para enterarte apenas te llegue un mensaje nuevo, aunque no tengas la web abierta.</p>
                <button onClick={handleActivarPushChat} disabled={activandoPushChat} style={{ background: COLORS.azulMedio, color: COLORS.text }} className="rounded-lg px-4 py-2 text-sm font-semibold whitespace-nowrap">
                  {activandoPushChat ? "Activando..." : "Activar notificaciones"}
                </button>
              </div>
            )}
            {errorPushChat && <div className="mb-4"><ErrorBox message={errorPushChat} /></div>}

            {tabInbox === "mensajes" && (
              <>
                {loadingInbox && <Loading label="Cargando tus conversaciones..." />}
                {!loadingInbox && conversaciones.length === 0 && (
                  <p style={{ color: COLORS.muted }} className="text-sm text-center py-16">
                    Todavía no tienes conversaciones. En cuanto alguien te contacte por una carta, o tú contactes a alguien, va a aparecer aquí.
                  </p>
                )}

                {!loadingInbox && conversaciones.length > 0 && (
                  <>
                    <h3 style={{ color: COLORS.azulPalido }} className="font-semibold mb-3 text-sm uppercase">Recientes</h3>
                    <div className="grid gap-3 mb-8">
                      {conversaciones.slice(0, 3).map((c) => (
                        <div
                          key={`reciente-${c.otherId}::${c.contexto}`}
                          onClick={() => setChatContext(c)}
                          style={{ background: COLORS.surface, border: `1px solid ${COLORS.azulPalido}55`, cursor: "pointer" }}
                          className="text-left rounded-xl p-4 flex items-center justify-between gap-4 hover:brightness-110 overflow-hidden"
                        >
                          <div className="min-w-0 overflow-hidden flex items-center gap-3">
                            <AvatarImg url={c.otherAvatar} size={36} />
                            <div className="min-w-0">
                              <div className="flex items-center gap-2 mb-1 min-w-0">
                                <p className="font-semibold shrink-0">{c.otherNombre}</p>
                                <Badge color={COLORS.azulClaro}>{c.contexto.length > 26 ? c.contexto.slice(0, 26) + "…" : c.contexto}</Badge>
                              </div>
                              <p style={{ color: COLORS.muted }} className="text-sm truncate">{c.ultimoMensaje}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2 shrink-0">
                            <p style={{ color: COLORS.muted }} className="text-xs whitespace-nowrap">
                              {new Date(c.fecha).toLocaleDateString("es-MX", { day: "numeric", month: "short" })}
                            </p>
                            <button onClick={(e) => { e.stopPropagation(); moverAPapelera(c.otherId, c.contexto); }} title="Mover a la papelera" style={{ color: COLORS.muted }} className="p-1 hover:brightness-125">
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>

                    <h3 style={{ color: COLORS.azulClaro }} className="font-semibold mb-3 text-sm uppercase">Todos tus chats</h3>
                    <div className="grid gap-3">
                      {conversaciones.map((c) => (
                        <div
                          key={`${c.otherId}::${c.contexto}`}
                          onClick={() => setChatContext(c)}
                          style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}`, cursor: "pointer" }}
                          className="text-left rounded-xl p-4 flex items-center justify-between gap-4 hover:brightness-110 overflow-hidden"
                        >
                          <div className="min-w-0 overflow-hidden flex items-center gap-3">
                            <AvatarImg url={c.otherAvatar} size={36} />
                            <div className="min-w-0">
                              <div className="flex items-center gap-2 mb-1 min-w-0">
                                <p className="font-semibold shrink-0">{c.otherNombre}</p>
                                <Badge color={COLORS.azulClaro}>{c.contexto.length > 26 ? c.contexto.slice(0, 26) + "…" : c.contexto}</Badge>
                              </div>
                              <p style={{ color: COLORS.muted }} className="text-sm truncate">{c.ultimoMensaje}</p>
                            </div>
                          </div>
                          <div className="flex items-center gap-2 shrink-0">
                            <p style={{ color: COLORS.muted }} className="text-xs whitespace-nowrap">
                              {new Date(c.fecha).toLocaleDateString("es-MX", { day: "numeric", month: "short" })}
                            </p>
                            <button onClick={(e) => { e.stopPropagation(); moverAPapelera(c.otherId, c.contexto); }} title="Mover a la papelera" style={{ color: COLORS.muted }} className="p-1 hover:brightness-125">
                              <Trash2 size={14} />
                            </button>
                          </div>
                        </div>
                      ))}
                    </div>
                  </>
                )}
              </>
            )}

            {tabInbox === "papelera" && (
              <>
                {loadingPapelera && <Loading label="Cargando la papelera..." />}
                {!loadingPapelera && papelera.length === 0 && (
                  <p style={{ color: COLORS.muted }} className="text-sm text-center py-16">
                    Tu papelera está vacía. Los chats que borres aparecen aquí y se eliminan definitivamente a los 7 días.
                  </p>
                )}
                {!loadingPapelera && papelera.length > 0 && (
                  <div className="grid gap-3">
                    {papelera.map((p) => {
                      const diasRestantes = Math.max(0, 7 - Math.floor((Date.now() - new Date(p.eliminado_en).getTime()) / (24 * 60 * 60 * 1000)));
                      return (
                        <div key={`${p.otro_perfil_id}::${p.contexto}`} style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }}
                          className="rounded-xl p-4 flex items-center justify-between gap-4 flex-wrap opacity-80">
                          <div className="min-w-0 overflow-hidden flex items-center gap-3">
                            <AvatarImg url={p.otro?.avatar_url} size={36} />
                            <div className="min-w-0">
                              <div className="flex items-center gap-2 mb-1 min-w-0">
                                <p className="font-semibold shrink-0">{p.otro?.nombre || "Usuario"}</p>
                                <Badge color={COLORS.azulClaro}>{p.contexto.length > 26 ? p.contexto.slice(0, 26) + "…" : p.contexto}</Badge>
                              </div>
                              <p style={{ color: COLORS.muted }} className="text-xs">
                                Se borra definitivamente en {diasRestantes} día{diasRestantes === 1 ? "" : "s"}
                              </p>
                            </div>
                          </div>
                          <button onClick={() => restaurarDePapelera(p.otro_perfil_id, p.contexto)}
                            style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55` }}
                            className="text-xs px-3 py-1.5 rounded-lg font-semibold whitespace-nowrap shrink-0">
                            Restaurar
                          </button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </>
            )}
          </div>
        )}

        {/* PLANES */}
        {view === "planes" && (
          <PlanesView session={session} perfil={perfil} onRequireLogin={() => setShowAccountModal(true)} onPlanActualizado={() => cargarOCrearPerfil(session)} />
        )}

        {/* WISHLIST / ALERTAS */}
        {view === "alertas" && session && (
          <AlertasPanel session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} onVerWishlistPublica={() => abrirWishlistPublica(session.user.id, perfil?.slug)} />
        )}

        {/* AYUDA */}
        {view === "ayuda" && <AyudaView perfil={perfil} />}

        {/* TORNEOS */}
        {view === "torneos" && (
          <TorneosView session={session} onRequireLogin={() => setShowAccountModal(true)} />
        )}

        {/* CATÁLOGO */}
        {view === "catalogo" && (
          <CatalogoView session={session} perfil={perfil} onIrAPlanes={() => (session ? setView("planes") : setShowAccountModal(true))} />
        )}

        {/* MIS PAGOS */}
        {view === "misPagos" && session && <MisPagosPanel session={session} />}

        {/* ADMIN */}
        {view === "admin" && session && perfil?.es_admin && <AdminPanel session={session} onVerPerfil={verPerfil} onEntrarComoSubperfil={entrarComoSubperfil} onAbrirSorteo={abrirSorteo} />}

        {/* MI MERCADO */}
        {view === "myMarket" && session && <MyMarketPanel session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} onIrAMiCuenta={() => setView("miCuenta")} />}

        {/* MI TIENDA */}
        {view === "myStore" && session && <MyStorePanel session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} onAbrirSorteo={abrirSorteo} onIrAMiCuenta={() => setView("miCuenta")} />}

        {/* SORTEOS */}
        {view === "sorteos" && <SorteosView session={session} onAbrirSorteo={abrirSorteo} />}
        {view === "sorteoDetalle" && selectedSorteoId && (
          <SorteoDetalleView sorteoId={selectedSorteoId} session={session} perfil={perfil}
            onVolver={() => { setSelectedSorteoId(null); setView("sorteos"); actualizarUrlCompartible({}); }}
            onRequireLogin={() => setShowAccountModal(true)} />
        )}

        {/* SUBASTAS */}
        {view === "subastas" && <SubastasView session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} onAbrirSubasta={abrirSubasta} onRequireLogin={() => setShowAccountModal(true)} />}
        {view === "subastaDetalle" && selectedSubastaId && (
          <SubastaDetalleView subastaId={selectedSubastaId} session={session} onAbrirChat={abrirChat}
            onVolver={() => { setSelectedSubastaId(null); setView("subastas"); actualizarUrlCompartible({}); }}
            onRequireLogin={() => setShowAccountModal(true)} />
        )}

        {/* STORE DETAIL */}
        {view === "storeDetail" && selectedStore && (
          <div>
            <button onClick={cerrarStore} style={{ color: COLORS.muted }} className="flex items-center gap-1 text-sm mb-6">
              <ChevronLeft size={16} /> Volver
            </button>
            <div style={{ background: COLORS.surface, border: `1px solid ${COLORS.surface2}` }} className="rounded-2xl mb-6" >
              <div style={{ height: 110, position: "relative", overflow: "hidden", background: `linear-gradient(120deg, ${COLORS.azul}, ${COLORS.azulMedio} 60%, ${COLORS.azulClaro})` }} className="rounded-t-2xl">
                <div style={{ position: "absolute", inset: 0, background: "repeating-linear-gradient(115deg, rgba(255,255,255,0.05) 0 2px, transparent 2px 22px)" }} />
              </div>
              <div className="p-6 pt-0">
                <div className="flex items-end gap-3 flex-wrap" style={{ marginTop: -34, position: "relative" }}>
                  <HoloAvatar perfil={selectedStore.perfiles} ringSize={78}>
                    <div style={{ border: `4px solid ${COLORS.surface}`, borderRadius: "9999px", background: COLORS.surface, flexShrink: 0 }}>
                      <AvatarImg url={selectedStore.perfiles?.avatar_url} size={72} />
                    </div>
                  </HoloAvatar>
                  <button onClick={() => verPerfil(selectedStore.perfil_id)} className="flex items-center gap-2 flex-wrap hover:underline pb-1" disabled={!selectedStore.perfil_id}>
                    <h2 style={{ fontFamily: "'Baloo 2', sans-serif" }} className="text-2xl font-bold">{selectedStore.nombre}</h2>
                  </button>
                  <div className="flex items-center gap-2 pb-1.5">
                    <PlanBadge perfil={selectedStore.perfiles} size="lg" />
                    <VerificadoBadge perfil={selectedStore.perfiles} />
                    <TiendaVerificadaBadge tienda={selectedStore} />
                    <NivelBadge total={storeDestellos} />
                    <VendedorBadge ventasCompletadas={storeVentasCompletadas} resenas={storeResenas} />
                    <TiempoRespuestaBadge perfil={selectedStore.perfiles} />
                    <CopiarLinkBoton param="tienda" slug={selectedStore.slug} />
                  </div>
                  {session && session.user.id !== selectedStore.perfil_id && (
                    <div className="ml-auto pb-1.5 flex items-center gap-2">
                      {/* Una tienda dada de alta por el Admin sin cuenta vinculada no
                          tiene perfil_id -- no hay a quién seguir, así que el botón
                          simplemente no aparece en vez de mandar una consulta rota. */}
                      {selectedStore.perfil_id && <SeguirBoton session={session} seguidoPerfilId={selectedStore.perfil_id} />}
                      <ReportarBoton session={session} tipo="perfil" tablaObjetivo="tiendas" objetivoId={selectedStore.id} objetivoPerfilId={selectedStore.perfil_id} objetivoNombre={selectedStore.nombre} />
                    </div>
                  )}
                </div>
              <div className="mt-3"><DiamanteEmblema perfil={selectedStore.perfiles} /></div>
              <div className="flex items-center gap-3 flex-wrap">
                <p style={{ color: COLORS.muted }} className="text-xs">👥 {storeSeguidores} seguidor{storeSeguidores === 1 ? "" : "es"}</p>
                <MiembroDesde perfil={selectedStore.perfiles} />
                {storeVentasCompletadas > 0 && <p style={{ color: COLORS.muted }} className="text-xs">🛒 {storeVentasCompletadas} venta{storeVentasCompletadas === 1 ? "" : "s"} completada{storeVentasCompletadas === 1 ? "" : "s"}</p>}
                {storeResenas.length > 0 && (
                  <div className="flex items-center gap-1">
                    <EstrellasDisplay valor={storeResenas.reduce((s, r) => s + r.estrellas, 0) / storeResenas.length} size={12} />
                    <p style={{ color: COLORS.muted }} className="text-xs">
                      {(storeResenas.reduce((s, r) => s + r.estrellas, 0) / storeResenas.length).toFixed(1)} ({storeResenas.length})
                    </p>
                  </div>
                )}
              </div>
              {selectedStore.sin_local ? (
                <p style={{ color: COLORS.muted }} className="mt-2 flex items-center gap-1 text-sm"><Store size={14} /> Sin local físico — venta en línea</p>
              ) : selectedStore.direccion ? (
                <p style={{ color: COLORS.muted }} className="mt-2 flex items-center gap-1 text-sm"><MapPin size={14} /> {selectedStore.direccion}</p>
              ) : null}
              {selectedStore.telefono && <p style={{ color: COLORS.muted }} className="mt-1 flex items-center gap-1 text-sm"><Phone size={14} /> {selectedStore.telefono}</p>}
              {(selectedStore.perfiles?.instagram || selectedStore.perfiles?.google_maps_url || selectedStore.perfiles?.sitio_web) && (
                <div className="flex gap-2 mt-3 flex-wrap">
                  {selectedStore.perfiles?.instagram && (
                    <a href={selectedStore.perfiles.instagram} target="_blank" rel="noreferrer"
                      style={{ border: `1px solid ${COLORS.azulMedio}88`, color: COLORS.azulMedio }} className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1">
                      Instagram <ExternalLink size={12} />
                    </a>
                  )}
                  {selectedStore.perfiles?.sitio_web && (
                    <a href={conProtocolo(selectedStore.perfiles.sitio_web)} target="_blank" rel="noreferrer"
                      style={{ border: `1px solid ${COLORS.gold}88`, color: COLORS.gold }} className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1">
                      Sitio web <ExternalLink size={12} />
                    </a>
                  )}
                  {selectedStore.perfiles?.google_maps_url && (
                    <a href={selectedStore.perfiles.google_maps_url} target="_blank" rel="noreferrer"
                      style={{ border: `1px solid ${COLORS.azulClaro}88`, color: COLORS.azulClaro }} className="rounded-lg px-3 py-1.5 text-xs font-semibold flex items-center gap-1">
                      <MapPin size={12} /> Google Maps
                    </a>
                  )}
                </div>
              )}
              {(selectedStore.direccion || (selectedStore.lat && selectedStore.lng)) && (
                <div className="mt-4 rounded-xl overflow-hidden" style={{ border: `1px solid ${COLORS.surface2}` }}>
                  <iframe
                    title="Ubicación en el mapa"
                    src={`https://www.google.com/maps?q=${
                      selectedStore.lat && selectedStore.lng
                        ? `${selectedStore.lat},${selectedStore.lng}`
                        : encodeURIComponent(`${selectedStore.direccion}, ${selectedStore.nombre}`)
                    }&output=embed`}
                    width="100%"
                    height="220"
                    style={{ border: 0 }}
                    loading="lazy"
                    referrerPolicy="no-referrer-when-downgrade"
                  />
                </div>
              )}
              </div>
            </div>

            {loadingStoreDetail ? <Loading label="Cargando inventario..." /> : (
              <>
                {/* sellado_tienda no tiene carpeta_id (migración 019 solo la agregó a
                    inventario_tienda/mercado_listings) -- una carpeta solo agrupa cartas sueltas. */}
                <CarpetasStorefront carpetas={storeCarpetas} items={storeInventory} tabla="inventario_tienda" onAbrirDetalle={abrirDetalle} />
                <h3 style={{ color: COLORS.azulPalido }} className="font-semibold mb-3 text-sm uppercase">Cartas sueltas</h3>
                <div className="grid gap-3 mb-8">
                  {storeInventory.filter((i) => i.en_venta !== false).filter(pasaFiltroTcg).length === 0 && <p style={{ color: COLORS.muted }} className="text-sm">{storeInventory.length === 0 ? "Esta tienda todavía no ha subido inventario." : `Esta tienda no tiene cartas de ${TCG_LABEL[tcgFiltro] || tcgFiltro} registradas.`}</p>}
                  {storeInventory.filter((i) => i.en_venta !== false).filter(pasaFiltroTcg).map((item) => (
                    <div key={item.id} onClick={() => abrirDetalle(item.id, "inventario_tienda")} style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${estaDestacado(item) ? COLORS.azulPalido + "66" : COLORS.azulClaro + "29"}`, cursor: "pointer" }} className="rounded-2xl p-4 flex justify-between items-center flex-wrap gap-2 transition-transform duration-200 hover:translate-x-1">
                      <div className="flex items-center gap-3">
                        {miniaturaListing(item) && <img src={miniaturaListing(item)} alt={item.carta} style={{ width: 72, height: 100, objectFit: "contain" }} />}
                        <div>
                          <div className="flex items-center gap-2 flex-wrap">
                            <p className="font-medium">{item.carta}</p>
                            <IdiomaBadge idioma={item.idioma} />
                            <EstadoCartaBadge condicion={item.condicion} />
                            <GradeoBadge gradeada={item.gradeada} grado_empresa={item.grado_empresa} grado_empresa_otro={item.grado_empresa_otro} grado_calificacion={item.grado_calificacion} />
                            <BoostBadge item={item} />
                          </div>
                          <p style={{ color: COLORS.muted }} className="text-xs">{item.set_nombre}</p>
                        </div>
                      </div>
                      <div className="text-right">
                        <PrecioConOferta precio={item.precio} precioAntes={item.precio_antes} size="md" />
                        {item.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs">ref. {item.precio_ref_fuente || "mercado"}: ~${Number(item.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                        <div className="flex gap-1 mt-1 justify-end">
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirChat(selectedStore.perfil_id, selectedStore.nombre, `${item.carta} (${item.set_nombre}) en ${selectedStore.nombre}`, null, null, selectedStore.perfiles?.avatar_url); }}
                            disabled={!selectedStore.perfil_id}
                            style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55`, opacity: selectedStore.perfil_id ? 1 : 0.4 }}
                            className="text-xs px-3 py-1.5 rounded-lg flex items-center gap-1">
                            <MessageCircle size={12} /> Contactar
                          </button>
                          <button
                            onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: "inventario_tienda", id: item.id, nombre: item.carta, precio: item.precio, imagen_url: miniaturaListing(item), contexto: `${item.carta} (${item.set_nombre}) en ${selectedStore.nombre}`, vendedorId: selectedStore.perfil_id, vendedorNombre: selectedStore.nombre, vendedorAvatar: selectedStore.perfiles?.avatar_url }); }}
                            disabled={!selectedStore.perfil_id || enElCarrito("inventario_tienda", item.id)}
                            style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: selectedStore.perfil_id ? 1 : 0.3 }}
                            className="text-xs px-2 py-1.5 rounded-lg flex items-center">
                            {enElCarrito("inventario_tienda", item.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
                <h3 style={{ color: COLORS.azulClaro }} className="font-semibold mb-3 text-sm uppercase">Producto sellado</h3>
                <div className="grid gap-3">
                  {storeSellado.filter(pasaFiltroTcg).length === 0 && <p style={{ color: COLORS.muted }} className="text-sm">{storeSellado.length === 0 ? "Sin producto sellado registrado." : `Sin producto sellado de ${TCG_LABEL[tcgFiltro] || tcgFiltro}.`}</p>}
                  {storeSellado.filter(pasaFiltroTcg).map((item) => (
                    <div key={item.id} onClick={() => abrirDetalle(item.id, "sellado_tienda")} style={{ background: `${COLORS.surface2}8c`, border: `1px solid ${estaDestacado(item) ? COLORS.azulPalido + "66" : COLORS.azulClaro + "29"}`, cursor: "pointer" }} className="rounded-2xl p-4 flex justify-between items-center flex-wrap gap-2 transition-transform duration-200 hover:translate-x-1">
                      <div className="flex items-center gap-3">
                        {item.imagen_url && <img src={item.imagen_url} alt={item.producto} style={{ width: 60, height: 84, objectFit: "contain" }} />}
                        <div className="flex items-center gap-2 flex-wrap">
                          <p className="font-medium">{item.producto}</p>
                          <BoostBadge item={item} />
                        </div>
                      </div>
                      <div className="text-right">
                        <PrecioConOferta precio={item.precio} precioAntes={item.precio_antes} size="md" />
                        {item.precio_ref_mxn && <p style={{ color: COLORS.muted }} className="text-xs">ref. {item.precio_ref_fuente || "mercado"}: ~${Number(item.precio_ref_mxn).toLocaleString("es-MX")}</p>}
                        <div className="flex gap-1 mt-1 justify-end">
                          <button
                            onClick={(e) => { e.stopPropagation(); abrirChat(selectedStore.perfil_id, selectedStore.nombre, `${item.producto} en ${selectedStore.nombre}`, null, null, selectedStore.perfiles?.avatar_url); }}
                            disabled={!selectedStore.perfil_id}
                            style={{ color: COLORS.azulPalido, border: `1px solid ${COLORS.azul}55`, opacity: selectedStore.perfil_id ? 1 : 0.4 }}
                            className="text-xs px-3 py-1.5 rounded-lg flex items-center gap-1">
                            <MessageCircle size={12} /> Contactar
                          </button>
                          <button
                            onClick={(e) => { e.stopPropagation(); agregarAlCarrito({ tabla: "sellado_tienda", id: item.id, nombre: item.producto, precio: item.precio, imagen_url: item.imagen_url, contexto: `${item.producto} en ${selectedStore.nombre}`, vendedorId: selectedStore.perfil_id, vendedorNombre: selectedStore.nombre, vendedorAvatar: selectedStore.perfiles?.avatar_url }); }}
                            disabled={!selectedStore.perfil_id || enElCarrito("sellado_tienda", item.id)}
                            style={{ color: COLORS.gold, border: `1px solid ${COLORS.gold}55`, opacity: selectedStore.perfil_id ? 1 : 0.3 }}
                            className="text-xs px-2 py-1.5 rounded-lg flex items-center">
                            {enElCarrito("sellado_tienda", item.id) ? <Check size={12} /> : <ShoppingCart size={12} />}
                          </button>
                        </div>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            )}
          </div>
        )}

        {view === "carpetaPublica" && selectedCarpetaPublicaId && (
          <CarpetaPublicaView
            carpetaId={selectedCarpetaPublicaId}
            onAbrirDetalle={abrirDetalle}
            onVerPerfil={verPerfil}
            onAbrirTienda={openStore}
            onVolver={() => { setSelectedCarpetaPublicaId(null); setView("search"); actualizarUrlCompartible({}); }}
          />
        )}

        {view === "wishlistPublica" && selectedWishlistPerfilId && (
          <WishlistPublicaView
            perfilId={selectedWishlistPerfilId}
            onVerPerfil={verPerfil}
            onVolver={() => { setSelectedWishlistPerfilId(null); setView("search"); actualizarUrlCompartible({}); }}
          />
        )}

        {view === "perfilPublico" && selectedPerfilId && (
          <PerfilPublicoView
            perfilId={selectedPerfilId}
            session={session}
            onVolver={cerrarPerfil}
            onAbrirChat={abrirChat}
            onVerTienda={verTiendaDesdePerfil}
            onAbrirDetalle={abrirDetalle}
            onSlugResuelto={(slug) => actualizarUrlCompartible(slug ? { u: slug } : {})}
            onVerWishlistPublica={(id, slug) => abrirWishlistPublica(id, slug)}
          />
        )}

        {view === "cartaDetalle" && selectedListing && (
          <CartaDetalleView
            id={selectedListing.id}
            tabla={selectedListing.tabla}
            session={session}
            onVolver={cerrarDetalle}
            onAbrirChat={abrirChat}
            onVerPerfil={verPerfil}
            onAgregarCarrito={agregarAlCarrito}
            enCarrito={enElCarrito(selectedListing.tabla, selectedListing.id)}
          />
        )}

        {(view === "privacidad" || view === "terminos") && (
          <LegalView tipo={view === "privacidad" ? "privacidad" : "terminos"} onVolver={() => setView(vistaAntesLegal)} />
        )}

        {view === "armarMazo" && (
          <ArmarMazoSection session={session} perfil={perfil} onAbrirChat={abrirChat} onVerTienda={verTiendaDesdePerfil} onIrAPlanes={() => setView("planes")} onAbrirDetalle={abrirDetalle} />
        )}
        {view === "competitivo" && (
          <CompetitivoSection session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} />
        )}
        {view === "comunidad" && <ComunidadView session={session} onVerPerfil={verPerfil} />}
        {view === "busquedas" && (
          <BusquedasView session={session} onAbrirChat={abrirChat} onVerPerfil={verPerfil} onRequireLogin={() => setShowAccountModal(true)} />
        )}
        {view === "siguiendo" && session && <SiguiendoView session={session} onVerPerfil={verPerfil} onVerTienda={verTiendaDesdePerfil} />}
        {view === "comprasVentas" && session && <ComprasVentasView session={session} />}
        {view === "modoEvento" && session && <ModoEventoView session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} />}
        {view === "coleccion" && (
          <ColeccionView session={session} perfil={perfil} onIrAPlanes={() => setView("planes")} onIrAMiTienda={() => setView("myStore")} />
        )}
        {view === "miCuenta" && session && (
          <MiCuentaView session={session} perfil={perfil} onGuardado={() => cargarOCrearPerfil(session)} onVerMiPerfil={() => verPerfil(session.user.id)} />
        )}
        {view === "recompensas" && session && <RecompensasView session={session} perfil={perfil} />}
        {view === "apariencia" && session && (
          <AparienciaView perfil={perfil} onCambio={() => setTemaVersion((v) => v + 1)} onIrAPlanes={() => setView("planes")} />
        )}
      </main>

      <footer style={{ position: "relative", zIndex: 1, borderTop: `1px solid ${COLORS.surface2}` }} className="px-4 sm:px-8 py-6 mt-10">
        <div className="max-w-5xl mx-auto flex items-center justify-center gap-4 flex-wrap text-xs" style={{ color: COLORS.muted }}>
          <button onClick={() => irALegal("privacidad")} className="hover:underline">Aviso de Privacidad</button>
          <span>·</span>
          <button onClick={() => irALegal("terminos")} className="hover:underline">Términos de Uso</button>
          <span>·</span>
          <span>© {new Date().getFullYear()} Encuentra Cartas</span>
        </div>
      </footer>
    </div>
  );
}
